window.SAA_EXAMS = [{"id":"exam-set-01","file":"set-01.md","num":"問題セット01","title":"第1分野：セキュアなアーキテクチャの設計","questions":[{"n":1,"topic":"アクセス管理","level":2,"body":["EC2インスタンス上で稼働するアプリケーションが、Amazon S3バケットへファイルを書き込んでいます。現在はIAMユーザーのアクセスキーをアプリケーションの設定ファイルに記載しており、セキュリティ監査で是正を求められました。運用負荷を最小限に抑えつつ、この指摘に対応する方法はどれですか。"],"options":[{"l":"A","html":"アクセスキーを設定ファイルから環境変数へ移し、90日ごとに手動でローテーションする"},{"l":"B","html":"アクセスキーをAWS Secrets Managerに保存し、アプリケーション起動時に取得するよう変更する"},{"l":"C","html":"S3へのアクセス権限を持つIAMロールを作成し、インスタンスプロファイルとしてEC2にアタッチしたうえで、設定ファイルからアクセスキーを削除する"},{"l":"D","html":"S3バケットポリシーで、EC2インスタンスのパブリックIPアドレスからのアクセスのみを許可する"}],"answer":["C"],"multi":false,"req":"","key":"AWS上で動くコンピューティング（EC2・Lambda・ECS）に権限を与える手段は<b>IAMロール</b>です。ロールが配布する認証情報は一時的なもので自動的にローテーションされるため、長期のアクセスキーそのものが不要になります。","reasons":[{"l":"A","html":"保管場所が変わっただけで長期認証情報は残り、手動ローテーションという運用負荷も残ります。"},{"l":"B","html":"Secrets Managerは「AWSの外部にある資格情報（DBのパスワードなど）」を管理する仕組みです。IAMロールを使えばアクセスキー自体が不要になるため、取得処理を実装する分だけ余計です。"},{"l":"D","html":"IPアドレスによる制限は認証ではありません。EIPの付け替えやSSRFによる悪用に耐えられず、監査指摘（長期認証情報の埋め込み）への回答にもなっていません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"クロスアカウント","level":2,"body":["外部のコンサルティング会社に、本番AWSアカウントのリソース構成を読み取り専用で調査してもらうことになりました。相手先は自社のAWSアカウントを保有しています。最も安全な方法はどれですか。"],"options":[{"l":"A","html":"本番アカウントにIAMユーザーを作成し、アクセスキーをメールで共有する"},{"l":"B","html":"読み取り専用ポリシーを付与したIAMロールを作成し、信頼ポリシーで相手のアカウントIDを指定したうえで、<b>外部ID（External ID）</b>の指定を必須にする"},{"l":"C","html":"ルートユーザーの認証情報を一時的に共有し、作業後にパスワードを変更する"},{"l":"D","html":"対象リソースのリソースポリシーで、すべてのプリンシパル（<code>\"Principal\": \"*\"</code>）からの読み取りを許可する"}],"answer":["B"],"multi":false,"req":"","key":"別アカウントへのアクセス提供は<b>ロールの引き受け（AssumeRole）</b>が基本形です。相手が他社（第三者）の場合は<b>外部ID</b>を必須にして、「混乱した代理人（Confused Deputy）問題」を防ぎます。","reasons":[{"l":"A","html":"長期のアクセスキーが社外に渡り、失効管理もできません。"},{"l":"C","html":"ルートユーザーは最初の設定以降は使用せず、共有は論外です。"},{"l":"D","html":"インターネット全体へ公開することになり、要件（特定の相手に限定）を満たしません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"組織統制","level":3,"body":["ある企業はAWS Organizationsで50個のアカウントを管理しています。データ主権の要件から、承認された3つのリージョン以外ではリソースを作成できないようにしたいと考えています。各メンバーアカウントには管理者権限を持つ開発者が存在し、<b>その開発者自身が制限を解除できてはなりません</b>。適切な方法はどれですか。"],"options":[{"l":"A","html":"各アカウントのIAMポリシーに、未承認リージョンを拒否する条件を追加する"},{"l":"B","html":"AWS Configルールで未承認リージョンのリソースを検出し、通知する"},{"l":"C","html":"各アカウントのIAMユーザーにアクセス許可境界（Permissions Boundary）を設定する"},{"l":"D","html":"Organizationsのサービスコントロールポリシー（SCP）で、未承認リージョンでのアクションを拒否し、対象のOUに適用する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>組織全体</b>に」「<b>メンバーアカウントの管理者でも解除できない</b>」上限を課せるのはSCPだけです。SCPはメンバーアカウントのルートユーザーにも効きます。","reasons":[{"l":"A","html":"アカウント内の管理者が自分でポリシーを編集できるため、制限として成立しません。"},{"l":"B","html":"Configは<b>検出と是正</b>の仕組みであり、作成そのものを<b>予防</b>できません。設問は予防を求めています。"},{"l":"C","html":"アクセス許可境界は個々のIAMエンティティに付ける上限で、アカウント全体・組織全体への強制にはなりません（設定漏れも起こります）。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":4,"topic":"データ保護","level":1,"body":["非公開のS3バケットに保管しているレポートPDFを、取引先の担当者1名に対し、<b>24時間だけ</b>ダウンロードさせたいと考えています。取引先はAWSアカウントを持っていません。最小の手間で実現する方法はどれですか。"],"options":[{"l":"A","html":"対象オブジェクトに対する事前署名URL（Presigned URL）を有効期限付きで発行して渡す"},{"l":"B","html":"バケットポリシーで当該オブジェクトをパブリック読み取り可能にし、24時間後に設定を戻す"},{"l":"C","html":"CloudFrontディストリビューションを作成し、OACでバケットに接続する"},{"l":"D","html":"取引先向けのIAMユーザーを作成し、24時間後に削除する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>特定のオブジェクト</b>を」「<b>期限付きで</b>」「<b>AWSアカウントを持たない相手に</b>」渡す要件は事前署名URLの定番です。","reasons":[{"l":"B","html":"公開期間中は誰でもアクセスでき、設定の戻し忘れという運用事故も招きます。"},{"l":"C","html":"CloudFront＋OACはバケットを非公開のままCDN配信する構成で、1回限りの共有には過剰です（期限付き配布をCloudFrontで行うなら署名付きURL／Cookieを併用します）。"},{"l":"D","html":"AWSアカウントを持たない相手にIAMユーザーを発行する運用は負荷が高く、削除漏れのリスクもあります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":5,"topic":"暗号化","level":2,"body":["本番稼働中のAmazon RDS for MySQLインスタンスが、作成時に暗号化を有効化していなかったことが判明しました。コンプライアンス要件を満たすため、保存データを暗号化する必要があります。適切な手順はどれですか。"],"options":[{"l":"A","html":"RDSコンソールで対象インスタンスの設定を変更し、暗号化を有効にする"},{"l":"B","html":"スナップショットを取得し、そのスナップショットを暗号化を指定してコピーしたうえで復元し、アプリケーションの接続先を新インスタンスへ切り替える"},{"l":"C","html":"マルチAZ配置に変更する。スタンバイ作成時に暗号化が適用される"},{"l":"D","html":"暗号化を有効にしたリードレプリカを同一リージョンに作成し、プライマリへ昇格させる"}],"answer":["B"],"multi":false,"req":"","key":"RDS・EBSとも、<b>暗号化は作成時にしか指定できません</b>。既存リソースの暗号化は「スナップショット → 暗号化を指定してコピー → 復元」が定石です。","reasons":[{"l":"A","html":"稼働中インスタンスの暗号化設定を後から有効化することはできません。"},{"l":"C","html":"マルチAZは可用性のための構成で、暗号化とは無関係です。"},{"l":"D","html":"未暗号化のインスタンスから暗号化されたリードレプリカを作成することはできません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"暗号化","level":2,"body":["大量の小さなオブジェクトをS3に書き込むアプリケーションで、SSE-KMSを使用しています。AWS KMSのリクエスト数が急増して料金が膨らみ、スロットリングも発生し始めました。監査要件があるため、キーの利用履歴は引き続き記録する必要があります。適切な対処はどれですか。"],"options":[{"l":"A","html":"暗号化方式をSSE-S3に変更する"},{"l":"B","html":"暗号化をやめ、バケットポリシーでHTTPS通信のみ許可する"},{"l":"C","html":"カスタマー管理キーを複数作成し、オブジェクトごとに使い分ける"},{"l":"D","html":"S3バケットキー（S3 Bucket Keys）を有効化する"}],"answer":["D"],"multi":false,"req":"","key":"S3バケットキーはバケット単位で短期間有効なキーを生成し、<b>KMSへのリクエスト数を大幅に削減</b>します。SSE-KMSのままなので監査要件も維持できます。","reasons":[{"l":"A","html":"SSE-S3ではCloudTrailにキー利用が記録されず、キーの管理・制御もできないため監査要件を満たせません。"},{"l":"B","html":"保存時の暗号化要件を放棄しており、要件違反です（HTTPSは転送時の保護）。"},{"l":"C","html":"キーを増やしてもリクエスト数の総量は変わらず、管理対象が増えるだけです。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a>"},{"n":7,"topic":"検出と監視","level":2,"body":["セキュリティチームから次の3つの要望が挙がりました。それぞれに最も適したサービスの組み合わせはどれですか。","1. S3バケット内に個人情報（クレジットカード番号など）が保存されていないか継続的に確認したい","2. EC2インスタンスのOSやライブラリに既知の脆弱性（CVE）がないか継続的に確認したい","3. 通常と異なる地域からのAPI呼び出しや、既知の不正IPとの通信を検知したい"],"options":[{"l":"A","html":"1: Amazon Macie ／ 2: Amazon Inspector ／ 3: Amazon GuardDuty"},{"l":"B","html":"1: Amazon GuardDuty ／ 2: Amazon Macie ／ 3: Amazon Inspector"},{"l":"C","html":"1: AWS Config ／ 2: Amazon Macie ／ 3: AWS CloudTrail"},{"l":"D","html":"1: Amazon Inspector ／ 2: Amazon GuardDuty ／ 3: AWS Security Hub"}],"answer":["A"],"multi":false,"req":"","key":"検出系の役割分担は固定です。<b>Macie＝S3の機密データ発見／Inspector＝脆弱性（CVE）診断／GuardDuty＝不審な振る舞いの検知</b>。","reasons":[{"l":"B","html":"3つのサービスの役割がすべて入れ替わっています。"},{"l":"C","html":"Configは「リソース設定の変更履歴と準拠状況」、CloudTrailは「誰がAPIを呼んだかの記録」であり、機密データの発見や脅威検知そのものは行いません。"},{"l":"D","html":"Security Hubは各種検出結果を<b>集約</b>するサービスで、単独で脅威を検知するものではありません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.13 検出系の整理</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A セキュリティ・運用管理</a>"},{"n":8,"topic":"多層防御","level":2,"body":["Network Load Balancer（NLB）の背後で稼働するWebアプリケーションに対し、SQLインジェクションとクロスサイトスクリプティングの防御を追加するよう指示されました。適切な構成はどれですか。"],"options":[{"l":"A","html":"NLBの前段にCloudFrontまたはApplication Load Balancerを配置し、そちらにWeb ACLを関連付ける"},{"l":"B","html":"NLBにAWS WAFのWeb ACLを関連付ける"},{"l":"C","html":"AWS Shield Standardを有効化する"},{"l":"D","html":"ネットワークACLで、攻撃元のIPアドレスを拒否する"}],"answer":["A"],"multi":false,"req":"","key":"AWS WAFを関連付けられるのは<b>CloudFront／ALB／API Gateway／AppSync／Cognitoユーザープール</b>です。<b>NLBやEC2には直接付けられない</b>ため、WAFを適用できる層を前段に置きます。","reasons":[{"l":"B","html":"NLBはL4のロードバランサーで、WAF（L7）を関連付けられません。"},{"l":"C","html":"Shieldが守るのはDDoS攻撃であり、SQLインジェクションのようなアプリケーション層の攻撃には対応しません。"},{"l":"D","html":"NACLはIPアドレス単位の遮断で、リクエストの中身を検査できません。攻撃元IPが変わるたびに後追いになります。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.5 AWS WAF</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":9,"topic":"多層防御","level":2,"body":["プライベートサブネット上のEC2インスタンスに対し、運用担当者がシェル接続して調査を行う必要があります。セキュリティポリシーにより、SSHキーの配布、踏み台ホストの設置、22番ポートの開放はいずれも認められていません。また、誰がいつ接続したかの記録が必要です。適切な方法はどれですか。"],"options":[{"l":"A","html":"クライアントVPNを構築し、VPN経由でSSH接続する"},{"l":"B","html":"パブリックサブネットに踏み台ホストを設置し、セキュリティグループで社内IPからのSSHのみ許可する"},{"l":"C","html":"AWS Systems Manager Session Managerを使用する（SSMエージェントとインスタンスプロファイルを構成し、必要に応じてVPCエンドポイントを配置する）"},{"l":"D","html":"インスタンスにパブリックIPを割り当て、EC2 Instance Connectで接続する"}],"answer":["C"],"multi":false,"req":"","key":"「<b>SSHキー不要・踏み台不要・インバウンドポート開放不要</b>」に「<b>操作ログが残る</b>」が揃えばSession Managerです。接続はSSMのアウトバウンド経路（またはVPCエンドポイント）を通ります。","reasons":[{"l":"A","html":"VPNを経由しても、最終的にSSHキーと22番ポートが必要になります。"},{"l":"B","html":"踏み台の設置と22番ポートの開放という、禁止されている条件そのものです。"},{"l":"D","html":"パブリックIPの割り当てはプライベートサブネットの前提に反し、インバウンド許可も必要になります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.3 多層防御</a>"},{"n":10,"topic":"責任共有モデル","level":1,"body":["AWSの責任共有モデルにおいて、<b>利用者（顧客）側の責任</b>に含まれるものはどれですか。"],"options":[{"l":"A","html":"RDSが稼働する物理ホストのハードウェア保守"},{"l":"B","html":"IAMポリシーの設計と、保存データを暗号化するかどうかの判断"},{"l":"C","html":"S3の物理ディスクの廃棄・消磁"},{"l":"D","html":"Lambda実行環境の基盤OSへのパッチ適用"}],"answer":["B"],"multi":false,"req":"","key":"マネージドの度合いが上がるほどAWS側の責任は増えますが、<b>データの分類・暗号化の要否・アクセス制御（IAM）は常に利用者の責任</b>です。","reasons":[{"l":"A","html":"物理ハードウェアの保守は「クラウド<b>の</b>セキュリティ」としてAWSの責任です。"},{"l":"C","html":"データセンター内の物理媒体の処分もAWSの責任範囲です。"},{"l":"D","html":"Lambdaは実行環境そのものがマネージドであり、基盤OSのパッチはAWSが行います（EC2であれば利用者の責任になります）。"}],"refs":"<a href=\"#d1\" data-go=\"d1\">第11章 11.4 責任共有モデル</a>"}]},{"id":"exam-set-02","file":"set-02.md","num":"問題セット02","title":"第2分野：弾力性に優れたアーキテクチャの設計","questions":[{"n":1,"topic":"スケーリング","level":2,"body":["Auto Scalingグループ配下のEC2インスタンスで動くWebアプリケーションが、メモリリークにより応答しなくなる事象が発生しています。OSは起動したままでHTTPリクエストに500エラーを返し続けますが、Auto Scalingはインスタンスを置き換えません。ALBのターゲットグループでは当該インスタンスが<code>unhealthy</code>と表示されています。適切な対処はどれですか。"],"options":[{"l":"A","html":"スケーリングポリシーのクールダウン期間を短縮する"},{"l":"B","html":"EC2の詳細モニタリングを有効化し、メトリクスの取得間隔を1分にする"},{"l":"C","html":"Auto Scalingグループのヘルスチェックタイプを「ELB」に変更する"},{"l":"D","html":"ALBのアイドルタイムアウト値を延長する"}],"answer":["C"],"multi":false,"req":"","key":"Auto Scalingの既定のヘルスチェックは<b>EC2ステータスチェックのみ</b>で、「OSは生きているがアプリが異常」という状態を検知できません。<b>ELBヘルスチェックを有効化</b>して初めて、ロードバランサーの判定に基づく置き換えが行われます。","reasons":[{"l":"A","html":"クールダウンは連続したスケーリング動作の間隔であり、異常インスタンスの検知とは無関係です。"},{"l":"B","html":"メトリクスの粒度が上がるだけで、置き換えの判断基準は変わりません。"},{"l":"D","html":"アイドルタイムアウトは接続の維持時間であり、異常の検知・置き換えには影響しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a>"},{"n":2,"topic":"疎結合","level":2,"body":["ECサイトの注文APIが、セール開始直後の数分間にリクエストが急増し、バックエンドのRDSへの書き込みが追いつかずエラーを返しています。注文処理は即時応答が必須ではなく、数十秒以内に完了すれば許容されます。最も適切な設計変更はどれですか。"],"options":[{"l":"A","html":"ALBでスティッキーセッションを有効化する"},{"l":"B","html":"RDSインスタンスを常時、ピーク時に耐えられるサイズへスケールアップする"},{"l":"C","html":"APIとバックエンド処理の間にAmazon SQSキューを挟み、ワーカーはキューの滞留数に応じてAuto Scalingさせる"},{"l":"D","html":"CloudFrontを前段に配置し、注文APIのレスポンスをキャッシュする"}],"answer":["C"],"multi":false,"req":"","key":"「<b>急増を吸収したい</b>」「<b>即時応答は不要</b>」はキューによる<b>バッファリング</b>の典型です。ワーカー数は<code>ApproximateNumberOfMessagesVisible</code>などキューの滞留量を基準にスケールさせます。","reasons":[{"l":"A","html":"スティッキーセッションは同一クライアントを同じターゲットへ固定する仕組みで、書き込み負荷は軽減しません。"},{"l":"B","html":"ピークに合わせた常時スケールアップは、平常時のコストが無駄になります。急増の度合いによっては上限にも当たります。"},{"l":"D","html":"書き込み（注文登録）はキャッシュできません。CloudFrontは読み取り配信の高速化のための仕組みです。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":3,"topic":"疎結合","level":3,"body":["Amazon SQS標準キューからメッセージを取得して処理するワーカーで、<b>同じ注文が2回処理される</b>事象が発生しています。処理時間はメッセージによって異なり、長いものでは10分近くかかります。キューの可視性タイムアウトは既定の30秒のままです。根本的な対処はどれですか。"],"options":[{"l":"A","html":"可視性タイムアウトを処理の最大所要時間より長く設定し、長時間処理では<code>ChangeMessageVisibility</code>で延長する。あわせて処理を冪等に実装する"},{"l":"B","html":"ロングポーリングを有効化し、受信待機時間を20秒にする"},{"l":"C","html":"デッドレターキュー（DLQ）を設定し、<code>maxReceiveCount</code>を1にする"},{"l":"D","html":"FIFOキューへ移行する"}],"answer":["A"],"multi":false,"req":"","key":"重複処理の原因は、<b>処理が終わる前に可視性タイムアウトが切れて、同じメッセージが別のワーカーに再配信されること</b>です。タイムアウトを処理時間に合わせるのが直接の対処で、標準キューは「最低1回」の配信であるため冪等な実装も必要です。","reasons":[{"l":"B","html":"ロングポーリングは空受信を減らしてAPIコール料金とレイテンシを改善する設定で、重複の原因には触れていません。"},{"l":"C","html":"DLQは失敗メッセージの隔離先です。<code>maxReceiveCount</code>を1にすると、一度でも再配信されたメッセージが即座に隔離され、正常な処理まで失われます。"},{"l":"D","html":"FIFOキューは順序保証と重複排除を提供しますが、スループット上限（300 TPS）という制約が付きます。可視性タイムアウトが処理時間より短い問題は解決せず、原因への対処になっていません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a>"},{"n":4,"topic":"イベント駆動","level":2,"body":["S3バケットに画像がアップロードされたことを契機に、<b>サムネイル生成</b>と<b>検索インデックスの更新</b>という2つの独立した処理を実行したいと考えています。一方の処理が失敗しても、もう一方に影響せず、それぞれ独立して再試行できる必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"S3イベント通知をAmazon SNSトピックへ送り、2つのSQSキューをサブスクライブさせて、それぞれのワーカーが処理する"},{"l":"B","html":"S3イベント通知で単一のLambda関数を起動し、その関数内で両方の処理を順番に実行する"},{"l":"C","html":"S3イベント通知を1つのSQSキューへ送り、2種類のワーカーが同じキューをポーリングする"},{"l":"D","html":"同じイベント種別・同じプレフィックスに対してS3イベント通知を2つ設定し、それぞれ別のLambda関数を起動する"}],"answer":["A"],"multi":false,"req":"","key":"1つのイベントを複数の処理系へ配り、<b>各処理系が独立して再試行できる</b>形が<b>SNSファンアウト（SNS＋複数SQS）</b>です。","reasons":[{"l":"B","html":"1つの関数に両処理を同居させると、片方の失敗がもう片方の再実行を巻き込みます（独立性がありません）。"},{"l":"C","html":"SQSのメッセージは1つのコンシューマーが取得すると他からは見えなくなるため、2種類の処理へ同じメッセージを届けられません。"},{"l":"D","html":"S3イベント通知は、同じイベント種別・同じプレフィックス範囲に対して重複する設定を作成できません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.2 Amazon SNS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":5,"topic":"災害対策","level":3,"body":["基幹システムのDR要件が「<b>RTO 10分以内、RPO 1分以内</b>」と定められました。コストは要件を満たす範囲で可能な限り低く抑える方針です。最も適切なDR戦略はどれですか。"],"options":[{"l":"A","html":"バックアップ＆リストア"},{"l":"B","html":"パイロットライト"},{"l":"C","html":"マルチサイト（アクティブ/アクティブ）"},{"l":"D","html":"ウォームスタンバイ"}],"answer":["D"],"multi":false,"req":"","key":"<b>要件を満たす戦略のうち、最も安価なものを選ぶ</b>のが原則です。ウォームスタンバイは縮小版の環境が常時稼働しているため、切り替えとスケールアウトで数分、非同期レプリケーションでRPOは数秒〜数分となり、要件を満たします。","reasons":[{"l":"A","html":"被災後に環境を構築するためRTOは数時間〜数日となり、要件を満たしません。"},{"l":"B","html":"コンピュート層が停止状態のため、起動とプロビジョニングに数十分かかり、RTO 10分を満たせません。"},{"l":"C","html":"要件は満たしますが、両リージョンで本番環境を常時稼働させるため最もコストが高く、「可能な限り低く」という方針に反します。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPOの指標</a>"},{"n":6,"topic":"高可用性","level":2,"body":["Amazon RDS for PostgreSQLで、日中に実行される集計レポートのクエリが重く、通常のトランザクション処理まで遅延しています。現在このDBはマルチAZ配置です。アプリケーションの変更は許容されます。適切な対処はどれですか。"],"options":[{"l":"A","html":"マルチAZ配置のスタンバイインスタンスへレポートクエリを向ける"},{"l":"B","html":"リードレプリカを作成し、レポートクエリの接続先をリードレプリカに変更する"},{"l":"C","html":"インスタンスクラスをより大きなものへ変更する"},{"l":"D","html":"毎朝スナップショットから別インスタンスを復元し、そこへレポートクエリを向ける"}],"answer":["B"],"multi":false,"req":"","key":"<b>読み取りのスケールはリードレプリカ</b>、<b>可用性はマルチAZ</b>という役割分担が頻出の対比です。分析系クエリをレプリカへ逃がせば、本番トランザクションへの影響を切り離せます。","reasons":[{"l":"A","html":"マルチAZのスタンバイインスタンスは<b>読み取りにも使用できません</b>（待機専用）。"},{"l":"C","html":"一時的には改善しますが、負荷の性質が異なる処理が同居する構造は変わらず、コストも増え続けます。"},{"l":"D","html":"復元したインスタンスのデータは取得時点のもので、最新のデータを参照できません。運用も煩雑です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"ステートレス化","level":2,"body":["Auto Scalingグループで運用しているWebアプリケーションで、スケールインが発生するたびに一部の利用者がログアウトされてしまいます。セッション情報は各EC2インスタンスのローカルディスクに保存されています。根本的な解決策はどれですか。"],"options":[{"l":"A","html":"ALBのスティッキーセッションを有効化する"},{"l":"B","html":"セッション情報をAmazon ElastiCache for RedisまたはAmazon DynamoDBへ外部化する"},{"l":"C","html":"セッション情報の保存先をEBSボリュームに変更する"},{"l":"D","html":"Auto Scalingグループの最小台数を引き上げ、スケールインを起こりにくくする"}],"answer":["B"],"multi":false,"req":"","key":"水平スケーリングの前提は<b>ステートレス</b>であることです。セッションを共有ストアへ外出しすれば、どのインスタンスが終了しても利用者の状態は失われません。","reasons":[{"l":"A","html":"スティッキーセッションは同じインスタンスへ誘導するだけで、そのインスタンスが終了すればセッションは失われます。"},{"l":"C","html":"EBSもインスタンスに紐づくため、終了時に同じ問題が起きます（単一AZの制約もあります）。"},{"l":"D","html":"台数を増やしてもスケールインは発生し、コストが増えるだけで根本原因は残ります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.4 Amazon ElastiCache</a>"},{"n":8,"topic":"高可用性","level":2,"body":["3つのアベイラビリティゾーンにまたがるVPCで、プライベートサブネットのEC2インスタンスがNAT Gateway経由で外部APIを呼び出しています。あるAZでNAT Gatewayに障害が発生したところ、<b>すべてのAZ</b>のインスタンスが外部と通信できなくなりました。再発を防ぐ構成はどれですか。"],"options":[{"l":"A","html":"NAT Gatewayをプライベートサブネットへ移動する"},{"l":"B","html":"NAT GatewayをNATインスタンスに置き換え、Auto Scalingグループで管理する"},{"l":"C","html":"インターネットゲートウェイをAZごとに追加する"},{"l":"D","html":"各AZにNAT Gatewayを配置し、各AZのサブネットのルートテーブルを自AZのNAT Gatewayに向ける"}],"answer":["D"],"multi":false,"req":"","key":"NAT Gatewayは<b>AZ単位のサービス</b>です。1台を全AZで共用すると、そのAZの障害が全体に波及します。<b>AZごとに配置し、ルートテーブルも自AZ向きにする</b>のが定石です。","reasons":[{"l":"A","html":"NAT Gatewayはパブリックサブネットに配置する必要があります。プライベートサブネットに置くと外部へ出られません。"},{"l":"B","html":"NATインスタンスは自前でパッチ・スケール・冗長化を管理する必要があり、可用性の観点でマネージドのNAT Gatewayより不利です。"},{"l":"C","html":"インターネットゲートウェイはVPCに1つで、AZの概念を持たず、AWS側で冗長化されています。増設という概念がありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"高可用性","level":3,"body":["オンラインゲームのマッチングサーバー（TCP/UDPを使用）を2つのリージョンで運用しています。現在はRoute 53のフェイルオーバールーティングで切り替えていますが、<b>DNSキャッシュの影響で切り替えに数分かかる</b>ことが問題視されています。より短時間で切り替える方法はどれですか。"],"options":[{"l":"A","html":"Route 53のレコードのTTLを0秒に設定する"},{"l":"B","html":"AWS Global Acceleratorを導入し、2つのリージョンのエンドポイントを登録する"},{"l":"C","html":"Amazon CloudFrontを前段に配置し、オリジンフェイルオーバーを設定する"},{"l":"D","html":"ALBのクロスゾーン負荷分散を有効化する"}],"answer":["B"],"multi":false,"req":"","key":"Global Acceleratorは<b>固定のAnycast IP</b>を入口とし、ヘルスチェックに基づいてAWSバックボーン内で転送先を切り替えるため、<b>DNSのTTLに依存せず数十秒で</b>フェイルオーバーできます。TCP/UDPにも対応します。","reasons":[{"l":"A","html":"TTLを短くしてもクライアントやリゾルバのキャッシュ挙動に依存し、確実な短縮にはなりません。クエリ料金と負荷も増えます。"},{"l":"C","html":"CloudFrontはHTTP/HTTPSの配信を対象とするサービスで、TCP/UDPのゲームトラフィックには適しません。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の分散設定であり、リージョン間の切り替えとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":10,"topic":"イベント駆動","level":2,"body":["Amazon S3のイベント通知で起動されるLambda関数が、下流サービスの一時障害で失敗しました。障害の復旧後に確認すると、<b>その間のイベントが失われていた</b>ことが判明しました。再発を防ぐ設定はどれですか。"],"options":[{"l":"A","html":"Lambda関数に送信先（Lambda Destinations）のonFailure、またはデッドレターキュー（DLQ）を設定する"},{"l":"B","html":"Lambda関数のタイムアウト値を最大の15分に延長する"},{"l":"C","html":"予約済み同時実行数を引き上げる"},{"l":"D","html":"Lambda関数の呼び出しを同期呼び出しに変更する"}],"answer":["A"],"multi":false,"req":"","key":"S3イベント通知は<b>非同期呼び出し</b>です。非同期呼び出しは自動で2回再試行されますが、それでも失敗したイベントは<b>破棄されます</b>。失われないようにするにはDLQまたはLambda Destinations（onFailure）で受け皿を用意します。","reasons":[{"l":"B","html":"失敗の原因は下流サービスの障害であり、実行時間の不足ではありません。"},{"l":"C","html":"同時実行数はスロットリング対策で、失敗イベントの保全とは別問題です。"},{"l":"D","html":"S3イベント通知の呼び出しモデルは非同期で固定されており、利用者が同期呼び出しへ変更することはできません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"}]},{"id":"exam-set-03","file":"set-03.md","num":"問題セット03","title":"第3分野：高パフォーマンスなアーキテクチャの設計","questions":[{"n":1,"topic":"データベース性能","level":2,"body":["Amazon DynamoDBをバックエンドに使うモバイルアプリで、商品マスタへの同じ読み取りリクエストが大量に発生しています。現在の応答時間は一桁ミリ秒ですが、<b>マイクロ秒台</b>まで短縮したいという要件が出ました。アプリケーションの改修は最小限に抑えたいと考えています。適切な対処はどれですか。"],"options":[{"l":"A","html":"グローバルセカンダリインデックス（GSI）を追加する"},{"l":"B","html":"Amazon ElastiCache for Memcachedを導入し、アプリケーション側にキャッシュ読み書きのロジックを実装する"},{"l":"C","html":"Amazon DynamoDB Accelerator（DAX）クラスターを導入する"},{"l":"D","html":"読み取りを強い整合性（Strongly Consistent Read）に変更する"}],"answer":["C"],"multi":false,"req":"","key":"<b>DynamoDB専用のインメモリキャッシュがDAX</b>です。DynamoDBと互換のAPIを持つため、アプリケーションの改修が最小限で済み、キャッシュヒット時はマイクロ秒台で応答します。","reasons":[{"l":"A","html":"GSIは別のキーで検索するための仕組みで、同一データの読み取りを高速化するものではありません。"},{"l":"B","html":"実現は可能ですが、キャッシュの読み書きと無効化のロジックをアプリ側に実装する必要があり、「改修は最小限」という要件に反します。"},{"l":"D","html":"強い整合性の読み取りは<b>消費キャパシティが2倍</b>になり、レイテンシも改善しません。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":2,"topic":"データベース性能","level":2,"body":["トラフィック増加にともない、AWS LambdaからAmazon RDS for MySQLへの接続が急増し、<code>Too many connections</code>エラーが発生するようになりました。クエリ自体は軽量です。適切な対処はどれですか。"],"options":[{"l":"A","html":"Amazon RDS Proxyを導入し、Lambdaの接続先をプロキシのエンドポイントに変更する"},{"l":"B","html":"リードレプリカを追加し、参照クエリを分散する"},{"l":"C","html":"Lambda関数のメモリ割り当てを増やす"},{"l":"D","html":"Lambda関数の予約済み同時実行数を上限まで引き上げる"}],"answer":["A"],"multi":false,"req":"","key":"Lambdaは同時実行のたびに新しい接続を張るため、<b>接続数の枯渇</b>が起こります。RDS Proxyが接続をプールして再利用するため、DB側の接続数を抑えられます（フェイルオーバー時間の短縮という利点もあります）。","reasons":[{"l":"B","html":"レプリカを増やしても、Lambdaが張る接続の総数が減るわけではありません。書き込みは依然としてプライマリに集中します。"},{"l":"C","html":"メモリ増強はCPU性能に比例しますが、接続数の問題とは無関係です。"},{"l":"D","html":"同時実行数を増やすと接続数はさらに増え、問題が悪化します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":3,"topic":"ストレージ性能","level":2,"body":["大量の並列ジョブが、S3バケットの単一プレフィックス配下（<code>s3://bucket/data/</code>）へ毎秒数千件の書き込みを行った結果、<code>503 Slow Down</code>エラーが返るようになりました。適切な対処はどれですか。"],"options":[{"l":"A","html":"バケットのバージョニングを無効化する"},{"l":"B","html":"S3 Transfer Accelerationを有効化する"},{"l":"C","html":"ストレージクラスをS3 Intelligent-Tieringに変更する"},{"l":"D","html":"オブジェクトキーを複数のプレフィックスへ分散させる（日付やハッシュ値をキーの先頭付近に含める）"}],"answer":["D"],"multi":false,"req":"","key":"S3の性能上限は<b>プレフィックス単位</b>（毎秒3,500 PUT／5,500 GET が目安）です。プレフィックスを分散させれば、その分だけ並列度を上げられます。","reasons":[{"l":"A","html":"バージョニングはリクエストレートの制限とは無関係です。"},{"l":"B","html":"Transfer Accelerationは<b>地理的に遠い場所からの転送</b>をエッジ経由で高速化する機能で、プレフィックス単位のスロットリングには効きません。"},{"l":"C","html":"ストレージクラスは保管コストと取り出し特性の話で、リクエストレートの上限は変わりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":4,"topic":"ストレージ性能","level":2,"body":["ゲノム解析のHPCワークロードで、数百台のEC2インスタンスが<b>数百GB/秒</b>のスループットで同一のデータセットへアクセスする必要があります。元データはS3バケットに保管されており、解析結果もS3へ書き戻します。適切なストレージはどれですか。"],"options":[{"l":"A","html":"Amazon EFS（汎用パフォーマンスモード）"},{"l":"B","html":"Amazon FSx for Lustre（S3バケットとリンクして使用）"},{"l":"C","html":"Amazon EBS io2 Block Express"},{"l":"D","html":"各インスタンスからS3 APIで直接読み書きする"}],"answer":["B"],"multi":false,"req":"","key":"<b>HPC・機械学習・数百GB/秒・S3との連携</b>というキーワードはFSx for Lustreです。S3バケットをリンクしてデータを遅延ロードし、結果を書き戻せます。","reasons":[{"l":"A","html":"EFSは汎用の共有ファイルストレージで、HPC向けの数百GB/秒には設計されていません。"},{"l":"C","html":"EBSは<b>単一インスタンスにアタッチする</b>ブロックストレージで、数百台からの同時共有には使えません。"},{"l":"D","html":"オブジェクトAPIでの直接アクセスは、POSIXファイルシステムを前提とする解析ソフトの要件を満たさず、要求スループットにも届きません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":5,"topic":"コンピューティング性能","level":2,"body":["t3.mediumインスタンスで稼働する分析バッチが、実行開始から数十分後に極端に遅くなる事象が繰り返し発生しています。CloudWatchで確認したところ、CPUクレジット残高がゼロになっていました。処理は常時CPUを高使用率で消費します。適切な対処はどれですか。"],"options":[{"l":"A","html":"Auto Scalingグループの最小台数を増やす"},{"l":"B","html":"メモリ最適化インスタンス（R系）へ変更する"},{"l":"C","html":"EBSボリュームをgp2からgp3へ変更する"},{"l":"D","html":"コンピューティング最適化インスタンス（C系）へ変更する"}],"answer":["D"],"multi":false,"req":"","key":"T系はバースト可能な汎用インスタンスで、<b>継続的に高いCPU使用率が必要なワークロードには不向き</b>です。常時CPUを使う処理はC系へ移します（暫定的にはT系のアンリミテッドモードでも回避できますが、追加料金が発生します）。","reasons":[{"l":"A","html":"台数を増やしても1台あたりのCPUクレジット枯渇は起き続け、コストだけが増えます。"},{"l":"B","html":"ボトルネックはCPUでありメモリではありません。"},{"l":"C","html":"ストレージI/Oではなく、CPUクレジットの枯渇が原因です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":6,"topic":"ネットワーク性能","level":2,"body":["東京リージョンでホストしているWebアプリケーション（HTTPS）を、欧州と北米の利用者にも高速に提供したいと考えています。コンテンツは画像などの静的アセットと、APIによる動的レスポンスの両方を含みます。オリジンは東京リージョンのまま維持します。適切な構成はどれですか。"],"options":[{"l":"A","html":"AWS Global Acceleratorを導入する"},{"l":"B","html":"Amazon CloudFrontを導入し、静的アセットをキャッシュしつつ、動的コンテンツもAWSバックボーン経由で配信する"},{"l":"C","html":"各リージョンにEC2インスタンスを立て、Route 53のレイテンシーベースルーティングで振り分ける"},{"l":"D","html":"ALBのクロスゾーン負荷分散を有効化する"}],"answer":["B"],"multi":false,"req":"","key":"HTTP/HTTPSで、<b>静的アセットのキャッシュ</b>が効く構成ではCloudFrontが第一候補です。動的コンテンツもエッジからオリジンまでAWSバックボーンを経由するため高速化されます。","reasons":[{"l":"A","html":"Global Acceleratorは<b>キャッシュを行いません</b>。静的アセットのオフロード効果が得られず、この要件ではCloudFrontに劣ります（TCP/UDPや固定IPが要件のときに選びます）。"},{"l":"C","html":"要件は「オリジンは東京のまま」です。マルチリージョン展開はデータ同期を含めて大掛かりで、前提に反します。"},{"l":"D","html":"クロスゾーン負荷分散はAZ間の均等分散の設定で、地理的なレイテンシとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"},{"n":7,"topic":"分析性能とコスト","level":2,"body":["S3に日次で蓄積されるCSV形式のアクセスログ（合計数TB）に対し、Amazon Athenaで日付を絞った集計を実行していますが、クエリが遅く課金額も大きくなっています。最も効果的な改善策はどれですか。"],"options":[{"l":"A","html":"データをParquet形式へ変換し、日付でパーティション分割する"},{"l":"B","html":"Amazon Redshiftクラスターを構築し、全データをロードする"},{"l":"C","html":"Athenaのワーカー数（並列度）を引き上げる"},{"l":"D","html":"対象バケットのストレージクラスをS3 Standard-IAへ変更する"}],"answer":["A"],"multi":false,"req":"","key":"Athenaは<b>スキャンしたデータ量</b>で課金されます。列指向フォーマット（Parquet／ORC）への変換と圧縮、そして<b>パーティション分割</b>でスキャン量そのものを減らすのが、速度とコストの両方に効く定石です。","reasons":[{"l":"B","html":"Redshiftは継続的・大規模なBI向けで、日次のアドホック集計には過剰です。クラスターの運用コストも発生します。"},{"l":"C","html":"Athenaはサーバーレスで、利用者が並列度を設定する仕組みはありません。"},{"l":"D","html":"ストレージクラスの変更は保管コストにしか影響せず、スキャン量もクエリ速度も変わりません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":8,"topic":"データベース性能","level":3,"body":["Amazon DynamoDBのテーブルで、プロビジョニングされたキャパシティには十分な余裕があるにもかかわらず、特定の時間帯に<code>ProvisionedThroughputExceededException</code>が頻発します。調査の結果、書き込みの大半が同一のパーティションキー値（当日の日付）に集中していました。適切な対処はどれですか。"],"options":[{"l":"A","html":"プロビジョニングされた書き込みキャパシティを2倍に増やす"},{"l":"B","html":"パーティションキーの設計を見直し、カーディナリティを高める（日付にランダムなサフィックスを付与するなどして分散させる）"},{"l":"C","html":"読み取りを強い整合性に変更する"},{"l":"D","html":"ローカルセカンダリインデックス（LSI）を追加する"}],"answer":["B"],"multi":false,"req":"","key":"DynamoDBのキャパシティは<b>パーティションごとに分配</b>されます。特定のキーに書き込みが集中する「ホットパーティション」では、テーブル全体に余裕があってもスロットリングします。<b>キー設計の見直し</b>が根本対処です。","reasons":[{"l":"A","html":"全体のキャパシティを増やしても、偏った1つのパーティションに割り当てられる分は限られるため、根本的な解決になりません。"},{"l":"C","html":"整合性モデルは読み取りの設定であり、書き込みの偏りとは無関係です（消費キャパシティが増えるだけです）。"},{"l":"D","html":"LSIは同一パーティションキー内で別のソートキーを使うための仕組みで、書き込みの集中をむしろ助長します。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":9,"topic":"検索性能","level":2,"body":["ECサイトの商品検索が、RDS上で<code>LIKE '%キーワード%'</code>による全件走査を行っているため非常に遅く、表記ゆれにも対応できていません。検索語のハイライトや関連度順の並び替えも求められています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"RDSのリードレプリカ"},{"l":"B","html":"Amazon Athena"},{"l":"C","html":"Amazon OpenSearch Service"},{"l":"D","html":"Amazon ElastiCache for Redis"}],"answer":["C"],"multi":false,"req":"","key":"<b>全文検索・あいまい検索・関連度順</b>という要件はOpenSearch Serviceです（ログのリアルタイム分析にも使われます）。","reasons":[{"l":"A","html":"レプリカを追加しても全件走査というクエリの性質は変わらず、表記ゆれにも対応できません。"},{"l":"B","html":"AthenaはS3上のデータへアドホックにSQLを実行するサービスで、対話的な検索機能の基盤には向きません。"},{"l":"D","html":"ElastiCacheはキーに対する高速な読み書きが得意で、全文検索エンジンではありません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.6 Amazon OpenSearch Service</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":10,"topic":"ネットワーク性能","level":3,"body":["数値流体解析（CFD）のHPCジョブを、MPIで通信する多数のEC2インスタンス上で実行します。ノード間通信のレイテンシが実行時間を左右するため、これを最小化する必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"クラスタープレイスメントグループに配置し、Elastic Fabric Adapter（EFA）を利用する"},{"l":"B","html":"スプレッドプレイスメントグループに配置する"},{"l":"C","html":"インスタンスを複数のアベイラビリティゾーンへ分散配置する"},{"l":"D","html":"AWS Global Acceleratorを経由させる"}],"answer":["A"],"multi":false,"req":"","key":"<b>HPC・MPI・ノード間の低レイテンシ</b>は、クラスタープレイスメントグループ（単一AZ内で近接配置）とEFA（OSカーネルを迂回する高速なノード間通信）の組み合わせです。","reasons":[{"l":"B","html":"スプレッドは少数の重要インスタンスを<b>別々のハードウェアへ分散</b>する配置で、可用性のための選択です。レイテンシはむしろ不利になります。"},{"l":"C","html":"AZ分散は可用性を高めますが、AZ間の物理距離のぶんレイテンシが増えます。"},{"l":"D","html":"Global Acceleratorはインターネット経由の利用者アクセスを高速化するサービスで、VPC内のノード間通信には関与しません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.4 ネットワークパフォーマンスの最適化</a>"}]},{"id":"exam-set-04","file":"set-04.md","num":"問題セット04","title":"第4分野：コストを最適化したアーキテクチャの設計","questions":[{"n":1,"topic":"ストレージのコスト","level":2,"body":["医療系の企業が、診断画像をS3に保存しています。アップロードから30日間は頻繁に参照されますが、その後はほとんど参照されません。ただし監査対応のため、<b>まれに発生する照会には数分以内に取り出せる</b>必要があり、データは7年間保持しなければなりません。最もコスト効率の高い構成はどれですか。"],"options":[{"l":"A","html":"すべてのオブジェクトをS3 Standardのまま保持し、7年後に削除する"},{"l":"B","html":"ライフサイクルポリシーで、30日後にS3 Glacier Deep Archiveへ移行し、7年後に失効させる"},{"l":"C","html":"ライフサイクルポリシーで、30日後にS3 Standard-IA、90日後にS3 Glacier Flexible Retrievalへ移行し、7年後に失効させる"},{"l":"D","html":"ライフサイクルポリシーで、30日後にS3 One Zone-IAへ移行して7年間保持する"}],"answer":["C"],"multi":false,"req":"","key":"取り出し要件が「<b>数分以内</b>」なので、Glacier Flexible Retrievalの迅速取り出し（1〜5分）で満たせます。段階的に安いクラスへ落とすのがライフサイクルの基本形です。","reasons":[{"l":"A","html":"最も高価なクラスのまま7年間保持することになり、コスト最適化になっていません。"},{"l":"B","html":"Deep Archiveの取り出しは標準12時間・大容量48時間で、「数分以内」を満たせません。"},{"l":"D","html":"One Zone-IAは単一AZ保管のため、AZ障害でデータが失われます。監査対応の長期保管には適しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":2,"topic":"コンピューティングのコスト","level":2,"body":["動画変換のバッチ処理を、EC2インスタンス群で毎晩実行しています。処理は<b>中断されても最初からやり直せる</b>設計で、完了までの時間には余裕があります。コストを最小化する方法はどれですか。"],"options":[{"l":"A","html":"スポットインスタンスを利用する（中断通知を受けたら処理を退避する）"},{"l":"B","html":"オンデマンドインスタンスで3年間のリザーブドインスタンスを購入する"},{"l":"C","html":"Savings Plansを1年分購入する"},{"l":"D","html":"Dedicated Hostを利用する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>中断されても良い</b>」「時間に余裕がある」はスポットインスタンスの適用条件です。最大90%の割引が得られます。","reasons":[{"l":"B","html":"RIは「常時稼働するワークロード」に対する前払い割引です。夜間のみの実行では稼働率が低く、割引を活かせません。"},{"l":"C","html":"Savings Plansも継続利用へのコミットメントで、中断可能なバッチには過剰です（ベース負荷があるならスポットと併用します）。"},{"l":"D","html":"Dedicated Hostは物理サーバーの専有で、ライセンス持ち込み等が目的です。最も高価な選択肢です。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":3,"topic":"ネットワークのコスト","level":3,"body":["プライベートサブネットの数百台のEC2インスタンスが、S3バケットへ毎日数TBのログを書き込んでいます。請求を確認すると、NAT Gatewayのデータ処理料金が突出していました。この費用を削減する方法はどれですか。"],"options":[{"l":"A","html":"S3用のゲートウェイ型VPCエンドポイントを作成し、ルートテーブルに追加する"},{"l":"B","html":"S3用のインターフェース型VPCエンドポイント（PrivateLink）を作成する"},{"l":"C","html":"NAT Gatewayの台数を1台に集約する"},{"l":"D","html":"EC2インスタンスにパブリックIPを割り当て、IGW経由で直接S3へ書き込む"}],"answer":["A"],"multi":false,"req":"","key":"S3とDynamoDB向けの<b>ゲートウェイ型エンドポイントは追加料金が無料</b>で、通信がNAT Gatewayを経由しなくなるため、処理料金とデータ転送料の両方を削減できます。","reasons":[{"l":"B","html":"インターフェース型はENIの時間料金とデータ処理料金が発生します。S3宛てならゲートウェイ型のほうが安く、要件に合致します。"},{"l":"C","html":"台数を減らすと単一AZ障害の影響範囲が広がるうえ、削減されるのは時間料金だけで、支配的なデータ処理料金は変わりません。"},{"l":"D","html":"プライベートサブネットの前提に反し、セキュリティが大きく後退します。データ転送料も発生します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":4,"topic":"データベースのコスト","level":2,"body":["社内の申請システムのデータベースが、平日の日中のみ利用され、夜間と週末はまったくアクセスがありません。現在はAurora PostgreSQLのプロビジョニング済みインスタンス（db.r6g.large）が24時間稼働しています。可用性要件は変わりません。最もコスト効率の高い構成はどれですか。"],"options":[{"l":"A","html":"Amazon DynamoDBへ移行する"},{"l":"B","html":"インスタンスサイズをdb.t4g.mediumへ変更する"},{"l":"C","html":"夜間と週末はクラスターを停止する運用をスクリプト化する"},{"l":"D","html":"Aurora Serverless v2に変更し、需要に応じてACUを自動増減させる"}],"answer":["D"],"multi":false,"req":"","key":"「<b>利用が断続的で、無負荷の時間帯が長い</b>」場合はAurora Serverless v2が適します。ACU単位で細かく増減し、アイドル時のコストを抑えられます。","reasons":[{"l":"A","html":"リレーショナルな申請ワークフローをDynamoDBへ移すのはアプリケーションの全面改修を伴い、コスト最適化の手段としては過剰です。"},{"l":"B","html":"サイズを下げても24時間分の課金は続き、ピーク時の性能も落ちます。"},{"l":"C","html":"Auroraクラスターの停止は最長7日で自動的に再開されるため、週末をまたぐ運用では停止し続けられません。スクリプトの保守も必要です。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":5,"topic":"コスト管理ツール","level":2,"body":["経理部門から次の2つの要望がありました。<b>2つ選択してください。</b>","1. 今月の利用額が予算の80%に達した時点でメール通知を受け取りたい","2. 過去12か月の推移をサービス別・タグ別に分析し、来月の利用額の予測を見たい","それぞれに適したサービスはどれですか。"],"options":[{"l":"A","html":"AWS Budgets（要望1）"},{"l":"B","html":"AWS Cost and Usage Report（要望1）"},{"l":"C","html":"AWS Cost Explorer（要望2）"},{"l":"D","html":"AWS Trusted Advisor（要望2）"},{"l":"E","html":"AWS Compute Optimizer（要望1）"}],"answer":["A","C"],"multi":true,"req":"","key":"<b>事前に止める＝Budgets（しきい値でアラート）／使った結果を分析する＝Cost Explorer（推移の可視化と予測）</b>という役割分担です。","reasons":[{"l":"B","html":"CURは時間単位・リソース単位の最も詳細な請求データをS3へ出力する仕組みで、それ自体に通知機能はありません（Athena等で分析します）。"},{"l":"D","html":"Trusted Advisorはコスト・性能・セキュリティ・耐障害性・クォータの5観点の点検で、予算超過の通知や推移分析は行いません。"},{"l":"E","html":"Compute Optimizerは機械学習でEC2などの適正サイズを推奨するサービスで、予算アラートの機能はありません。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.1 コスト管理ツールの使い分け</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.9〜10.11 コスト管理サービス</a>"},{"n":6,"topic":"コンピューティングのコスト","level":2,"body":["スタートアップが、1日あたり数千回だけ実行される画像リサイズ処理をEC2の常時稼働インスタンス（t3.small × 2台）で運用しています。1回の処理は3秒以内に完了します。運用の手間とコストの両方を下げたいと考えています。適切な移行先はどれですか。"],"options":[{"l":"A","html":"AWS Batchへ移行する"},{"l":"B","html":"EC2をスポットインスタンスへ変更する"},{"l":"C","html":"Auto Scalingグループを設定し、最小台数を1に下げる"},{"l":"D","html":"AWS Lambdaへ移行し、S3イベントで起動する"}],"answer":["D"],"multi":false,"req":"","key":"「<b>短時間・イベント駆動・実行回数が限られる</b>」ワークロードでは、アイドル時間に課金されないLambdaが最もコスト効率に優れ、サーバー管理も不要になります。","reasons":[{"l":"A","html":"Batchは15分を超えるような長時間のバッチ計算向けです。3秒の処理には過剰で、裏側のコンピュート費用も発生します。"},{"l":"B","html":"スポットでも常時稼働のアイドル時間には課金され、中断対応の実装も必要になります。"},{"l":"C","html":"1台分のアイドルコストは残り、サーバー管理の手間も減りません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":7,"topic":"ストレージのコスト","level":3,"body":["データ分析チームが利用するS3バケットには、<b>アクセスパターンがまったく予測できない</b>オブジェクトが数億件あります。運用の手間をかけずにコストを最適化したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"ライフサイクルポリシーで、30日後に一律でStandard-IAへ移行する"},{"l":"B","html":"S3 Intelligent-Tieringを適用する"},{"l":"C","html":"CloudWatchメトリクスでアクセス頻度を毎月分析し、手動でクラスを変更する"},{"l":"D","html":"すべてをS3 Glacier Instant Retrievalへ移行する"}],"answer":["B"],"multi":false,"req":"","key":"「<b>アクセスパターンが不明・変動する</b>」「<b>運用の手間をかけたくない</b>」はIntelligent-Tieringの適用条件です。監視料金のみで自動的に階層を移動し、取り出し料金はかかりません。","reasons":[{"l":"A","html":"一律移行すると、頻繁にアクセスされるオブジェクトでは取り出し料金がかさみ、かえって高くつく場合があります。"},{"l":"C","html":"数億件を手動で分類する運用は現実的ではなく、「手間をかけずに」という要件に反します。"},{"l":"D","html":"Glacier Instant Retrievalは最低90日の保存期間があり、早期削除では残期間分が課金されます。頻繁にアクセスされるオブジェクトでは取り出し料金も発生します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":8,"topic":"ネットワークのコスト","level":2,"body":["動画配信サービスで、S3に置いた動画ファイルを世界中の視聴者へ直接配信しています。S3からインターネットへのデータ転送料金が急増しました。視聴される動画には強い偏りがあり、上位1%のファイルが再生回数の大半を占めています。コスト削減に最も効果的な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Accelerationを有効化する"},{"l":"B","html":"S3のストレージクラスをOne Zone-IAへ変更する"},{"l":"C","html":"CloudFrontを前段に配置して配信し、S3バケットはOACで非公開にする"},{"l":"D","html":"リクエスタ支払い（Requester Pays）を有効化する"}],"answer":["C"],"multi":false,"req":"","key":"CloudFrontはエッジでキャッシュするためオリジン（S3）へのリクエストとデータ転送が大幅に減り、<b>CloudFrontからの配信単価はS3からの直接配信より安い</b>のが一般的です。アクセスに偏りがあるほどキャッシュヒット率が上がり効果的です。","reasons":[{"l":"A","html":"Transfer Accelerationは遠距離からの<b>アップロード</b>を高速化する機能で、追加料金が発生します。配信コストは下がりません。"},{"l":"B","html":"ストレージクラスは<b>保管</b>コストの話で、インターネットへのデータ転送料は変わりません。"},{"l":"D","html":"リクエスタ支払いは転送料金を取得側に負担させる仕組みで、一般の視聴者向け配信には適用できません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":9,"topic":"コンピューティングのコスト","level":3,"body":["3年間の運用実績があるWebサービスで、ベースとなる負荷は常時一定、日中のみ負荷が1.5倍になり、月末のバッチ処理では一時的に3倍まで増加します。バッチ処理は中断可能です。最もコスト効率の高い購入方法の組み合わせはどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"ベース負荷分にスポットインスタンスを利用する"},{"l":"B","html":"ベース負荷分に Compute Savings Plans（またはリザーブドインスタンス）を適用する"},{"l":"C","html":"すべての負荷をオンデマンドインスタンスでまかなう"},{"l":"D","html":"月末のバッチ処理分にスポットインスタンスを利用する"},{"l":"E","html":"月末のバッチ処理分に3年間のリザーブドインスタンスを購入する"}],"answer":["B","D"],"multi":true,"req":"","key":"<b>ベース負荷はコミットメント割引（Savings Plans／RI）、変動分はオンデマンド、中断可能なバースト分はスポット</b>という重ね方が定石です。","reasons":[{"l":"A","html":"ベース負荷は常時必要な処理です。中断の可能性があるスポットをサービスの土台に使うのは適しません。"},{"l":"C","html":"常時一定の負荷にオンデマンドを使い続けるのは、割引の機会を捨てていることになります。"},{"l":"E","html":"月末のみの一時的な負荷に3年コミットするのは、稼働率が低く割引を活かせません。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.1 Amazon EC2</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a>"},{"n":10,"topic":"データベースのコスト","level":2,"body":["IoTプラットフォームがDynamoDBにセンサーデータを保存しています。データは直近90日間のみ照会され、それ以前のデータは年に数回の分析でしか使われませんが、テーブルの容量が増え続けコストを圧迫しています。適切な対処はどれですか。"],"options":[{"l":"A","html":"プロビジョニングされた読み取りキャパシティを引き下げる"},{"l":"B","html":"TTL属性を設定して90日経過した項目を自動削除し、削除前のデータはDynamoDB StreamsやエクスポートでS3へ退避して分析はAthenaで行う"},{"l":"C","html":"テーブルをオンデマンドキャパシティモードへ変更する"},{"l":"D","html":"グローバルセカンダリインデックスを追加し、古いデータを分離する"}],"answer":["B"],"multi":false,"req":"","key":"DynamoDBのストレージ費用は項目数に比例します。<b>TTLで自動削除</b>して容量を抑え、めったに使わない履歴は<b>S3に退避してAthenaで分析</b>するのが定石です。","reasons":[{"l":"A","html":"キャパシティの調整はスループット課金の話で、増え続けるストレージ費用には効きません。"},{"l":"C","html":"課金方式が変わるだけで、保存しているデータ量そのものは減りません。"},{"l":"D","html":"GSIはインデックス分のストレージとキャパシティを<b>追加で消費</b>するため、コストはむしろ増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"}]},{"id":"exam-set-05","file":"set-05.md","num":"問題セット05","title":"総合（本番の分野比率に合わせた混合セット）","questions":[{"n":1,"topic":"マルチアカウント統制","level":2,"body":["企業が新規事業ごとにAWSアカウントを発行する方針を決めました。各アカウントには、ログの集約、ガードレールの適用、標準的なネットワーク構成が最初から備わっている必要があります。アカウント発行のたびに手作業で設定する運用は避けたいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Control Towerでランディングゾーンを構築し、Account Factoryでアカウントを発行する"},{"l":"B","html":"AWS Organizationsを有効化し、アカウント作成後にSCPを手動で適用する"},{"l":"C","html":"AWS CloudFormation StackSetsのみで各アカウントへリソースを展開する"},{"l":"D","html":"AWS Service Catalogで承認済みのアカウント設定を配布する"}],"answer":["A"],"multi":false,"req":"","key":"「<b>マルチアカウント基盤をベストプラクティス構成で自動的に立ち上げる</b>」のがControl Towerです。Organizations、SCP、ログ集約、アカウント発行（Account Factory）を一括で用意します。","reasons":[{"l":"B","html":"Organizations単体では請求統合とSCPの適用まで。ログ集約やネットワークの標準化、発行の自動化は自前で組む必要があります。"},{"l":"C","html":"StackSetsはリソースの展開手段であり、アカウントそのものの発行やガードレールの枠組みは提供しません（Control Towerの内部でも使われます）。"},{"l":"D","html":"Service Catalogは利用者に承認済みの構成テンプレートを配布する仕組みで、アカウント基盤の構築とは目的が異なります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.5 AWS Organizations</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":2,"topic":"オンプレミス接続","level":3,"body":["本社データセンターとAWS間を、<b>帯域が安定した専用線</b>で接続しています。監査部門から「経路上のデータはすべて暗号化されていること」という指摘を受けました。既存の接続方式は維持したまま、最小の変更で対応する方法はどれですか。"],"options":[{"l":"A","html":"転送するデータをアプリケーション側でS3へアップロードしてから処理する"},{"l":"B","html":"Direct Connectを解約し、Site-to-Site VPNのみに切り替える"},{"l":"C","html":"Direct Connect Gatewayを追加する"},{"l":"D","html":"Direct Connectの上にIPsec VPN（またはMACsec）を構成し、通信を暗号化する"}],"answer":["D"],"multi":false,"req":"","key":"<b>Direct Connectは既定では暗号化されません</b>。専用線の帯域特性を保ったまま暗号化要件を満たすには、その上にIPsec VPNを重ねるか、対応回線でMACsecを使います。","reasons":[{"l":"A","html":"経路の暗号化要件に対する回答になっておらず、アプリケーションの作り替えも必要になります。"},{"l":"B","html":"VPNはインターネット経由のため、専用線の「安定した帯域・低レイテンシ」という前提を失います。"},{"l":"C","html":"DX Gatewayは複数リージョン・複数VPCへ接続を広げる仕組みで、暗号化とは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":3,"topic":"暗号鍵の管理","level":3,"body":["金融機関のシステムで、規制により「<b>暗号鍵は専有のハードウェアで管理し、FIPS 140-2 レベル3の検証を受けていること</b>」「鍵素材はクラウド事業者にも一切触らせないこと」が求められています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Secrets Manager"},{"l":"B","html":"AWS KMSのカスタマー管理キー（自動ローテーション有効）"},{"l":"C","html":"AWS KMSのAWSマネージドキー"},{"l":"D","html":"AWS CloudHSM"}],"answer":["D"],"multi":false,"req":"","key":"<b>専有HSM・FIPS 140-2 レベル3・鍵素材の完全な自己管理</b>という要件はCloudHSMです（KMSのカスタムキーストアと組み合わせることもできます）。","reasons":[{"l":"A","html":"Secrets Managerは資格情報の保管とローテーションのサービスで、暗号鍵のハードウェア要件とは関係ありません。"},{"l":"B","html":"KMSはマネージドな共有HSM基盤で、専有ハードウェアの要件を満たしません。"},{"l":"C","html":"AWSマネージドキーはポリシーの変更もできず、要件から最も遠い選択肢です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":4,"topic":"API設計","level":2,"body":["社内向けのモノリシックなアプリケーションから、参照系の機能だけを切り出してAPIとして外部パートナーへ公開することになりました。パートナーごとに<b>呼び出し回数の上限</b>を設け、超過分は遮断する必要があります。バックエンドはLambda関数で実装します。適切な構成はどれですか。"],"options":[{"l":"A","html":"Lambda関数URLを発行し、関数内で呼び出し回数をカウントする"},{"l":"B","html":"Application Load BalancerのターゲットにLambdaを登録し、WAFのレートベースルールで制限する"},{"l":"C","html":"Amazon API Gatewayで公開し、APIキーと使用量プランでパートナーごとの上限を設定する"},{"l":"D","html":"CloudFrontを前段に置き、キャッシュのTTLを長くする"}],"answer":["C"],"multi":false,"req":"","key":"<b>利用者ごとの流量制御（APIキー＋使用量プラン）</b>はAPI Gatewayの標準機能です。スロットリングでバックエンドも保護できます。","reasons":[{"l":"A","html":"カウント処理を自前で実装・保守することになり、超過時の遮断やプラン管理も作り込みが必要です。"},{"l":"B","html":"WAFのレートベースルールは主にIP単位の制限で、パートナー単位の契約上限を管理する仕組みとしては粗すぎます。"},{"l":"D","html":"キャッシュは負荷軽減には効きますが、契約上の呼び出し回数の上限管理にはなりません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.1 Amazon API Gateway</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":5,"topic":"コンテナ移行","level":2,"body":["オンプレミスで稼働するDockerアプリケーションをAWSへ移行します。開発チームにKubernetesの運用経験はなく、<b>EC2インスタンスの管理も避けたい</b>と考えています。既存のDockerfileはそのまま使う方針です。適切な構成はどれですか。"],"options":[{"l":"A","html":"Amazon EKS on Amazon EC2（マネージドノードグループ）"},{"l":"B","html":"Amazon ECS on AWS Fargate"},{"l":"C","html":"Amazon EC2上にDockerを導入して直接実行する"},{"l":"D","html":"AWS Lambdaのコンテナイメージサポートを利用する"}],"answer":["B"],"multi":false,"req":"","key":"<b>Kubernetesの記述がない＋サーバー管理をしたくない</b>＝ECS on Fargateです。AWSサービスとの統合が容易で、運用負荷が最も低くなります。","reasons":[{"l":"A","html":"Kubernetesの学習・運用コストが発生し、EC2ノードの管理も残ります。要件と逆方向です。"},{"l":"C","html":"OSのパッチ適用、スケーリング、障害対応をすべて自前で担うことになります。"},{"l":"D","html":"Lambdaは15分の実行時間制限とイベント駆動の実行モデルが前提です。常時稼働するWebアプリケーションの移行先としては制約が大きすぎます。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.3 サーバーレステクノロジーの活用</a>"},{"n":6,"topic":"高可用性","level":3,"body":["単一AZのEC2インスタンス1台とRDSシングルAZ構成で動いているアプリケーションを、<b>AZ障害が起きてもサービスを継続できる</b>構成に変更します。実施すべき対策はどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2のインスタンスタイプを1つ大きいサイズへ変更する"},{"l":"B","html":"RDSのリードレプリカを同一AZに1台追加する"},{"l":"C","html":"EC2をAuto Scalingグループに入れ、複数AZのサブネットにまたがってALB配下で最低2台稼働させる"},{"l":"D","html":"EBSのスナップショットを1時間おきに取得する"},{"l":"E","html":"RDSをマルチAZ配置に変更する"}],"answer":["C","E"],"multi":true,"req":"","key":"AZ障害への耐性は「<b>複数AZに冗長化する</b>」ことでしか得られません。アプリ層はASG＋ELB＋マルチAZ、DB層はマルチAZ配置が定型です。","reasons":[{"l":"A","html":"スケールアップは処理能力の話で、AZ障害時には同じように停止します。"},{"l":"B","html":"同一AZにレプリカを置いても、そのAZが落ちれば同時に失われます（別AZへ置けば可用性にも寄与しますが、自動フェイルオーバーはマルチAZ配置の役割です）。"},{"l":"D","html":"スナップショットは復旧の材料であり、障害時にサービスを継続させるものではありません（RPOの改善にとどまります）。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.2 可用性と耐久性</a>"},{"n":7,"topic":"データ取り込み","level":2,"body":["数万台のIoTデバイスから送られるテレメトリを、<b>追加のコードを書かずに</b>S3へ集約し、Parquet形式に変換して保存したいと考えています。取り込みは数分程度の遅延が許容されます。運用負荷を最小にする構成はどれですか。"],"options":[{"l":"A","html":"Kinesis Data Streamsで受け、独自のコンシューマーアプリケーションでS3へ書き出す"},{"l":"B","html":"Amazon Data Firehose（旧 Kinesis Data Firehose）でS3へ配信し、形式変換を有効にする"},{"l":"C","html":"Amazon SQSで受け、Lambdaで変換してS3へ書き出す"},{"l":"D","html":"Amazon EMRクラスターを常時稼働させ、デバイスから直接書き込ませる"}],"answer":["B"],"multi":false,"req":"","key":"「<b>S3などへ配送するだけ</b>」「<b>コード不要・完全マネージド</b>」「数分の遅延が許容」はFirehoseの適用条件です。Parquetへの形式変換も組み込み機能で行えます。","reasons":[{"l":"A","html":"Data Streamsはコンシューマーを自分で実装・運用する前提で、順序保証や再処理が必要な場合に選びます。今回は要件に含まれていません。"},{"l":"C","html":"実装と運用が必要になり、「追加のコードを書かずに」という要件に反します。"},{"l":"D","html":"常時稼働のEMRはコストが高く、取り込みの入口としても適しません。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":8,"topic":"データ変換と分析","level":2,"body":["S3に蓄積した生ログに対し、<b>スキーマを自動的に推論してカタログ化</b>し、ETL処理を行ったうえで、アナリストがSQLでアドホックに分析できるようにしたいと考えています。サーバーの管理は避けたい方針です。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"AWS Glue（クローラーとETLジョブ）＋ Amazon Athena"},{"l":"B","html":"Amazon EMR（Spark）＋ Amazon Redshift"},{"l":"C","html":"AWS Lambda（変換）＋ Amazon RDS"},{"l":"D","html":"Amazon Kinesis Data Streams ＋ Amazon QuickSight"}],"answer":["A"],"multi":false,"req":"","key":"<b>スキーマ推論とカタログ化＝Glueクローラー／サーバーレスETL＝Glueジョブ／S3への直接SQL＝Athena</b>。いずれもサーバー管理が不要です。","reasons":[{"l":"B","html":"EMRはクラスターの構成管理が必要で、Redshiftも常時稼働のクラスター運用を伴います。「サーバー管理を避けたい」に反します。"},{"l":"C","html":"Lambdaでの大規模ETLは実行時間の制約があり、RDSはアドホックな大規模分析の基盤には適しません。"},{"l":"D","html":"Data Streamsはリアルタイム取り込みの仕組みで、蓄積済みデータのカタログ化・変換は行いません。QuickSightは可視化であり、データを取得する層が別途必要です。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.2 AWS Glue</a> ／ <a href=\"#analytics\" data-go=\"analytics\">第7章 7.3 Amazon Athena</a>"},{"n":9,"topic":"ロードバランサーの選択","level":2,"body":["サードパーティ製の仮想ファイアウォールアプライアンスを導入し、VPCへ出入りするトラフィックをすべて検査したうえで転送する構成を作ります。アプライアンスは複数台で冗長化し、スケールさせる必要があります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Network Load Balancer"},{"l":"B","html":"Application Load Balancer"},{"l":"C","html":"Gateway Load Balancer"},{"l":"D","html":"Amazon Route 53の加重ルーティング"}],"answer":["C"],"multi":false,"req":"","key":"<b>サードパーティの仮想アプライアンス（ファイアウォール、IDS/IPS）を透過的に挟み込み、冗長化・スケールさせる</b>のがGateway Load Balancerの役割です（GENEVEプロトコルでカプセル化します）。","reasons":[{"l":"A","html":"NLBはL4の負荷分散で、アプライアンスへの透過的な引き込み（ミラーではなくインライン挿入）の仕組みは持ちません。"},{"l":"B","html":"ALBはL7のHTTP/HTTPS向けで、すべてのトラフィックを透過的に検査する用途には使えません。"},{"l":"D","html":"Route 53はDNSレベルの振り分けで、パケットの検査経路を構成するものではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":10,"topic":"ストレージのコスト","level":2,"body":["数百台のEC2インスタンスで、汎用SSD（gp2）のEBSボリュームを使用しています。現在のIOPS使用状況を調べたところ、多くのボリュームで割り当てIOPSを持て余している一方、一部のボリュームではIOPS不足のためにサイズだけを大きくして対応していました。コストと性能の両面で最も適切な対処はどれですか。"],"options":[{"l":"A","html":"gp3へ変更し、必要なIOPSとスループットを容量とは独立に設定する"},{"l":"B","html":"すべてのボリュームをio2 Block Expressへ変更する"},{"l":"C","html":"IOPS不足のボリュームだけをさらに大きなサイズへ拡張する"},{"l":"D","html":"スループット最適化HDD（st1）へ変更する"}],"answer":["A"],"multi":false,"req":"","key":"gp3は<b>IOPSとスループットを容量から切り離して設定</b>できます。容量を増やしてIOPSを稼ぐ必要がなくなり、gp2より単価も安くなります。","reasons":[{"l":"B","html":"io2 Block Expressは最高水準の性能を要するDB向けで、単価が高くコスト最適化に反します。"},{"l":"C","html":"容量課金が増え続けるうえ、余っているボリュームの無駄は解消されません。"},{"l":"D","html":"st1はシーケンシャルなスループット向けのHDDで、ブートボリュームにも使えず、ランダムIOPSを要する用途には不適です。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"}]},{"id":"exam-set-06","file":"set-06.md","num":"問題セット06","title":"複合問題（分野をまたぐ設計判断）","questions":[{"n":1,"topic":"セキュリティ × コスト","level":3,"body":["医療情報を含む監査ログをS3に保管します。要件は次の3つです。(1) 保存データは<b>キーの利用履歴を追跡できる方式</b>で暗号化する、(2) 法定保存期間は7年で、<b>照会は年に1回程度、取り出しに数時間かかっても構わない</b>、(3) 7年間の総コストを最小化する。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"SSE-KMSで暗号化し、S3 Standardのまま7年間保管する"},{"l":"B","html":"SSE-S3で暗号化し、ライフサイクルポリシーで30日後にS3 Glacier Deep Archiveへ移行する"},{"l":"C","html":"SSE-KMS（S3バケットキー有効）で暗号化し、ライフサイクルポリシーで30日後にS3 Glacier Deep Archiveへ移行して7年後に失効させる"},{"l":"D","html":"SSE-KMS（S3バケットキー有効）で暗号化し、ライフサイクルポリシーで30日後にS3 One Zone-IAへ移行する"}],"answer":["C"],"multi":false,"req":"①キー利用履歴の追跡＝<b>SSE-KMS</b>（第1分野）／②取り出しは数時間でよい＝<b>Deep Archiveが許容できる</b>（第3分野）／③7年の総コスト最小（第4分野）","key":"3つすべてを満たす選択肢は1つだけです。SSE-KMSで監査要件を満たしつつ、<b>S3バケットキー</b>でKMSリクエスト料金を抑え、取り出し時間の許容度を使ってDeep Archiveまで落とします。","reasons":[{"l":"A","html":"要件(1)は満たしますが、最も高いクラスで7年間保管するため要件(3)に反します。"},{"l":"B","html":"SSE-S3はCloudTrailにキーの利用が記録されず、要件(1)を満たしません。コストだけを見て暗号化方式の要件を落とした典型例です。"},{"l":"D","html":"One Zone-IAは単一AZ保管でAZ障害時にデータが失われ、法定保存の要件に耐えません。コストもDeep Archiveより高くなります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":2,"topic":"可用性 × コスト","level":3,"body":["基幹システムのDR要件が「<b>RPO 5分以内、RTO 30分以内</b>」に決まりました。現在は東京リージョンのAurora MySQLで稼働しています。コストは要件を満たす範囲で最小にする方針です。適切な構成はどれですか。"],"options":[{"l":"A","html":"東京リージョン内でAuroraクラスターを3つのAZに拡張し、リードレプリカを2台追加する"},{"l":"B","html":"大阪リージョンに本番同等のAuroraクラスターとアプリ層を常時稼働させ、Route 53で両系へ振り分ける"},{"l":"C","html":"Auroraの自動バックアップを大阪リージョンへコピーし、被災時にCloudFormationで環境一式を構築して復元する"},{"l":"D","html":"Auroraグローバルデータベースで大阪リージョンにセカンダリクラスターを構成し、アプリ層はAMIとIaCテンプレートを用意して被災時に起動する"}],"answer":["D"],"multi":false,"req":"①RPO 5分以内＝<b>継続的なレプリケーションが必須</b>（第2分野）／②RTO 30分以内＝<b>DB以外は被災後の起動で間に合う</b>（第2分野）／③コスト最小（第4分野）","key":"RPOの要件がデータ層の常時レプリケーションを要求し、RTO 30分という緩さがアプリ層の事前起動を不要にします。この組み合わせが<b>パイロットライト</b>で、Auroraグローバルデータベース（通常1秒未満のレプリケーション）がそれを実現します。","reasons":[{"l":"A","html":"マルチAZとリードレプリカは<b>同一リージョン内</b>の可用性・性能対策です。リージョン障害に対するDRにはなりません。"},{"l":"B","html":"要件は満たしますが、本番環境を二重に常時稼働させるため最も高コストで、方針③に反します。"},{"l":"C","html":"バックアップからの復元はRPOがバックアップ間隔に縛られ、構築・復元にも時間がかかるため①②の双方を満たせません。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.3 RTOとRPOの指標</a>"},{"n":3,"topic":"パフォーマンス × コスト","level":3,"body":["ゲームのランキング機能をDynamoDBで実装しています。トラフィックは<b>毎日ほぼ同じ形で推移し、予測可能</b>です。要件は (1) 読み取りレイテンシをマイクロ秒台にする、(2) 同じ上位100件が繰り返し読まれる、(3) キャパシティ料金を最小化する、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"オンデマンドキャパシティモードに変更し、DAXを前段に置く"},{"l":"B","html":"プロビジョニング済みキャパシティ＋Auto Scalingを使い、DynamoDB Accelerator（DAX）を前段に置く"},{"l":"C","html":"プロビジョニング済みキャパシティ＋Auto Scalingを使い、読み取りを強い整合性に変更する"},{"l":"D","html":"グローバルテーブルを有効化し、最寄りリージョンから読み取る"}],"answer":["B"],"multi":false,"req":"①マイクロ秒＝<b>DAX</b>（第3分野）／②同一データの繰り返し読み取り＝キャッシュが効く（第3分野）／③負荷が予測可能＝<b>プロビジョニング済みが最安</b>（第4分野）","key":"レイテンシ要件はDAXが、コスト要件はプロビジョニング済み＋Auto Scalingが満たします。<b>性能の手段とコストの手段は別々に選ぶ</b>のがこの種の設問の解き方です。","reasons":[{"l":"A","html":"オンデマンドは負荷が読めない場合に適し、予測可能な負荷ではプロビジョニング済みより割高になります（要件③に反する）。"},{"l":"C","html":"強い整合性は消費キャパシティが2倍になり、レイテンシも改善しません。①③の両方に反します。"},{"l":"D","html":"グローバルテーブルは地理的な分散とマルチリージョンの可用性のための機能で、マイクロ秒のレイテンシ要件には応えず、コストも増えます。"}],"refs":"<a href=\"#database\" data-go=\"database\">第4章 4.3 Amazon DynamoDB</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.4 データベースのコスト最適化</a>"},{"n":4,"topic":"セキュリティ × 弾力性","level":3,"body":["決済処理をSQSキュー経由の非同期処理に変更します。要件は (1) メッセージ本文に含まれるカード情報を<b>保存時に暗号化し、キーへのアクセスを制御する</b>、(2) 下流の障害で処理に失敗したメッセージを<b>失わずに隔離する</b>、(3) 処理は最長10分かかることがあり、<b>二重決済は許されない</b>、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"FIFOキューをSSE-KMSで暗号化し、可視性タイムアウトを30秒のままにする"},{"l":"B","html":"SSE-SQS（SQS管理キー）のキューを使い、可視性タイムアウトを既定の30秒のままにし、失敗時はアプリケーションから再送する"},{"l":"C","html":"SSE-KMS（カスタマー管理キー）を有効にしたキューを使い、デッドレターキューを設定し、可視性タイムアウトを処理時間より長く設定したうえで処理を冪等に実装する"},{"l":"D","html":"メッセージ本文をアプリケーション側で暗号化し、デッドレターキューの代わりにCloudWatchアラームで失敗を検知する"}],"answer":["C"],"multi":false,"req":"①キー制御が必要＝<b>SSE-KMS（カスタマー管理キー）</b>（第1分野）／②失敗メッセージの保全＝<b>DLQ</b>（第2分野）／③処理10分・二重決済不可＝<b>可視性タイムアウトの延長＋冪等性</b>（第2分野）","key":"3つの要件がそれぞれ別の機能に対応します。<b>要件ごとに担当する機能を割り当てられるか</b>が問われています。","reasons":[{"l":"A","html":"FIFOは順序と重複排除を提供しますが、<b>重複排除の対象は5分以内の送信</b>であり、処理中の可視性タイムアウト切れによる再配信は防げません（③未達）。DLQもなく②も満たしません。"},{"l":"B","html":"SSE-SQSではキーのアクセス制御ができず①を満たしません。可視性タイムアウト30秒のままでは10分の処理中に再配信され、③にも反します。"},{"l":"D","html":"独自の暗号化実装は鍵管理の負担が大きく、アラームは通知であって<b>メッセージの保全にはならない</b>ため②を満たしません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.8 AWS KMS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":5,"topic":"セキュリティ × パフォーマンス","level":3,"body":["有料会員向けの動画をS3から配信します。要件は (1) 世界中の会員に低遅延で配信する、(2) <b>契約期間中の会員だけ</b>が視聴でき、URLを共有されても第三者は視聴できない、(3) S3バケットは<b>インターネットから直接アクセスできない</b>、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"CloudFrontを配置し、OACでS3へのアクセスをCloudFrontからのみに限定し、視聴者には有効期限付きの署名付きCookieを発行する"},{"l":"B","html":"CloudFrontを配置し、S3バケットをパブリック読み取りにして、CloudFrontの地理的制限で国を限定する"},{"l":"C","html":"S3の静的ウェブサイトホスティングを有効にし、事前署名URLを都度発行する"},{"l":"D","html":"CloudFrontを配置し、OACでS3を非公開にしたうえで、WAFのレートベースルールで過剰なアクセスを遮断する"}],"answer":["A"],"multi":false,"req":"①世界中へ低遅延＝<b>CloudFront</b>（第3分野）／②視聴者の限定＝<b>署名付きURL／Cookie</b>（第1分野）／③オリジンの非公開＝<b>OAC</b>（第1分野）","key":"<b>OACは「CloudFrontだけがS3を読める」ための仕組み、署名付きURL／Cookieは「正当な視聴者だけが配信を受けられる」ための仕組み</b>で、役割が異なります。複数ファイルからなる動画配信ではCookieが適します。","reasons":[{"l":"B","html":"バケットをパブリックにすると③に反します。地理的制限は国単位のフィルタであり、会員かどうかの判定にはなりません（②未達）。"},{"l":"C","html":"静的ウェブサイトホスティングはCDNを経由しないため①を満たさず、パブリックアクセスの設定も③に反します。"},{"l":"D","html":"①③は満たしますが、WAFのレート制限は流量の制御であって会員の識別ではないため②を満たしません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"},{"n":6,"topic":"弾力性 × パフォーマンス","level":3,"body":["ALBとAuto Scalingグループで動くWebアプリケーションで、次の2つの問題が同時に起きています。(1) スケールインのたびに利用者がログアウトされる、(2) ピーク時にRDSのCPU使用率が100%に張り付き、参照系のクエリが詰まる。<b>それぞれに対する適切な対処を2つ選択してください。</b>"],"options":[{"l":"A","html":"セッション情報をAmazon ElastiCache for RedisまたはDynamoDBへ外部化する"},{"l":"B","html":"RDSをマルチAZ配置に変更し、スタンバイへ参照系クエリを向ける"},{"l":"C","html":"ALBでスティッキーセッションを有効にし、スケールイン保護をすべてのインスタンスに設定する"},{"l":"D","html":"RDSにリードレプリカを追加し、参照系クエリの接続先をレプリカへ向ける"},{"l":"E","html":"Auto Scalingグループの最小台数をピーク時の台数に固定する"}],"answer":["A","D"],"multi":true,"req":"①スケールインで状態が消える＝<b>ステートレス化</b>（第2分野）／②参照系でDBが詰まる＝<b>読み取りのスケール</b>（第3分野）","key":"症状が2つあるときは<b>それぞれ別の層の問題</b>として切り分けます。状態はアプリ層の外へ、読み取り負荷はレプリカへ、が定型です。","reasons":[{"l":"B","html":"マルチAZ配置のスタンバイは<b>読み取りにも使えません</b>。可用性の対策であり、②の解決にはなりません。"},{"l":"C","html":"スティッキーセッションは同じインスタンスへ誘導するだけで、そのインスタンスが終了すればセッションは失われます。スケールイン保護を常時掛けるのは弾力性そのものを捨てる対処です。"},{"l":"E","html":"ピーク台数に固定すると常時コストが増えるうえ、①の原因（ローカルにセッションを持つ設計）は残ります。"}],"refs":"<a href=\"#d2\" data-go=\"d2\">第12章 12.1 スケーリング戦略</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.1 Amazon RDS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.3 データベースとパフォーマンス</a>"},{"n":7,"topic":"コスト × 運用","level":2,"body":["開発・検証用のAWSアカウントで請求が想定を超えました。調査の結果、(1) 開発用EC2が夜間と週末も稼働している、(2) gp2ボリュームが大量にあり、IOPSを持て余している、(3) 使われていないElastic IPが数十個ある、ことが分かりました。<b>すぐに効果が出る対処を2つ選択してください。</b>"],"options":[{"l":"A","html":"EC2インスタンスをより小さいインスタンスタイプへ変更する"},{"l":"B","html":"スケジュールされたスケーリング（またはInstance Scheduler）で、平日夜間と週末はインスタンスを停止する"},{"l":"C","html":"すべてのEC2に3年間のリザーブドインスタンスを購入する"},{"l":"D","html":"アカウントにコスト配分タグを設定する"},{"l":"E","html":"gp2ボリュームをgp3へ変更し、必要なIOPSとスループットを個別に指定する"}],"answer":["B","E"],"multi":true,"req":"①稼働時間の無駄＝<b>止める</b>（第4分野）／②過剰なプロビジョニング＝<b>適正化する</b>（第4分野・第3分野）／③「すぐに効果が出る」＝実施が容易で即座に請求に反映されるもの","key":"コスト削減の基本は「<b>止める・落とす・コミットする</b>」の3手。開発環境では<b>止める</b>が最も効果的で、gp2→gp3は性能を落とさずに単価が下がります。","reasons":[{"l":"A","html":"性能要件を確認せずサイズを下げると開発効率を損ないます。Compute Optimizerの推奨を確認してから行う手順です。なお未使用のElastic IPは、アタッチされていない状態で課金されるため削除が必要です。"},{"l":"C","html":"開発環境は停止・廃止の可能性が高く、3年コミットは無駄になるリスクが大きい選択です。"},{"l":"D","html":"タグは可視化と配賦のための準備で、それ自体は請求額を下げません（次の打ち手を決めるためには有用です）。"}],"refs":"<a href=\"#d4\" data-go=\"d4\">第14章 14.3 コンピューティングのコスト最適化</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.6 AWS Trusted Advisor</a>"},{"n":8,"topic":"セキュリティ × 可用性 × コスト","level":3,"body":["Organizationsで管理する50アカウントのAPI操作ログを一元管理します。要件は (1) <b>全アカウント・全リージョン</b>の操作を漏れなく記録する、(2) ログは<b>アカウント管理者でも改ざん・削除できない</b>、(3) 保管は5年間で、コストを抑える、の3つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"CloudWatch Logsに全アカウントのログを集約し、保持期間を5年に設定する"},{"l":"B","html":"各アカウントで個別にCloudTrailを有効化し、それぞれのアカウントのS3バケットへ保存する。バケットポリシーで削除を禁止する"},{"l":"C","html":"管理アカウントで組織証跡を作成し、管理アカウントのS3バケットへ集約する。バージョニングを有効にし、S3 Standardのまま5年間保管する"},{"l":"D","html":"管理アカウントで組織証跡を作成し、専用のログアカウントのS3バケットへ集約する。バケットはオブジェクトロック（コンプライアンスモード）を有効にし、ライフサイクルでGlacierクラスへ移行する"}],"answer":["D"],"multi":false,"req":"①全アカウント・全リージョンの記録＝<b>組織証跡</b>（第1分野）／②管理者でも消せない＝<b>オブジェクトロック（コンプライアンスモード）＋アカウント分離</b>（第1分野）／③5年保管のコスト＝<b>ライフサイクルでGlacierへ</b>（第4分野）","key":"「<b>改ざんできない</b>」という要件は、バケットポリシーのような<b>変更できる防御</b>では満たせません。コンプライアンスモードのオブジェクトロックと、証跡アカウントの分離（権限の分離）が答えになります。","reasons":[{"l":"A","html":"CloudWatch Logsは検索・アラート向けで、長期保管のコスト効率ではS3＋Glacierに劣り、改ざん防止の要件も満たしません。"},{"l":"B","html":"個別設定は設定漏れが起きやすく、同一アカウント内にログがあるため、そのアカウントの管理者がポリシーを変更して削除できてしまいます（①②未達）。"},{"l":"C","html":"集約はできますが、バージョニングは削除を防ぐ仕組みではなく（権限があれば完全削除が可能）、5年間Standardで保管するためコストにも反します。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a> ／ <a href=\"#d4\" data-go=\"d4\">第14章 14.2 ストレージのコスト最適化</a>"},{"n":9,"topic":"パフォーマンス × 弾力性","level":3,"body":["工場のセンサーから送られるデータを、リアルタイム処理と日次のバッチ分析の<b>両方</b>で使っています。要件は (1) センサーごとの<b>時系列の順序</b>を保つ、(2) リアルタイム処理と分析処理が<b>同じデータを独立して読める</b>、(3) 障害時は<b>過去24時間分を再処理</b>できる、の3つです。取り込みの入口として適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon Kinesis Data Streams（センサーIDをパーティションキーにし、保持期間を24時間以上に設定する）"},{"l":"B","html":"Amazon SQS標準キューを2本用意し、送信側が両方へ送る"},{"l":"C","html":"Amazon Data Firehose（旧 Kinesis Data Firehose）でS3へ配信し、各処理はS3を読む"},{"l":"D","html":"Amazon SNSトピックに発行し、2つのSQSキューをサブスクライブさせる"}],"answer":["A"],"multi":false,"req":"①センサーごとの順序＝<b>パーティションキー単位の順序保証</b>（第3分野）／②複数のコンシューマーが同じデータを読む＝<b>ストリームの保持</b>（第2分野）／③再処理＝<b>保持期間内の巻き戻し</b>（第2分野）","key":"<b>「同じデータを複数のアプリが何度でも読める」「順序が保たれる」「再処理できる」</b>の3点が揃うのはKinesis Data Streamsです。SQSはメッセージを取得すると他から見えなくなり、再処理もできません。","reasons":[{"l":"B","html":"標準キューは順序を保証せず（①未達）、消費したメッセージは再取得できません（③未達）。送信側で二重送信する設計も壊れやすくなります。"},{"l":"C","html":"Firehoseは配送専用で<b>データを保持せず</b>、コンシューマーがストリームを読み直すこともできません。順序の保証もありません。"},{"l":"D","html":"ファンアウトで②は満たせますが、SQSに入った時点で順序保証と再処理性は失われます（①③未達）。"}],"refs":"<a href=\"#analytics\" data-go=\"analytics\">第7章 7.1 Amazon Kinesis</a> ／ <a href=\"#integration\" data-go=\"integration\">第6章 6.1 Amazon SQS</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":10,"topic":"全分野","level":3,"body":["社内の申請システムをAWSへ移行します。要件は (1) 利用は<b>平日日中のみ</b>で、夜間・週末はアクセスがない、(2) AZ障害時もサービスを継続する、(3) 保存データは暗号化し、DBはインターネットから到達できない、(4) 運用要員が少ないため<b>管理の手間を最小化</b>する、の4つです。最も適切な構成はどれですか。"],"options":[{"l":"A","html":"ALB＋EC2 Auto Scalingをマルチにに配置し、DBはEC2上にMySQLを構築して暗号化する"},{"l":"B","html":"ALB＋ECS on Fargate（Auto Scaling）をマルチAZに配置し、DBはAurora Serverless v2をプライベートサブネットで暗号化して構成する"},{"l":"C","html":"単一AZのEC2にアプリとMySQLを同居させ、夜間は停止するスクリプトを組む"},{"l":"D","html":"ALB＋EC2 Auto Scalingをマルチにに配置し、DBはRDSシングルAZをパブリックサブネットに配置して暗号化する"}],"answer":["B"],"multi":false,"req":"①日中のみ利用＝<b>アイドル時のコストを抑えたい</b>（第4分野）／②AZ障害への耐性＝<b>マルチAZ</b>（第2分野）／③暗号化とプライベート配置（第1分野）／④管理の手間＝<b>マネージド／サーバーレス</b>（第2・4分野）","key":"4つすべてを満たす選択肢は1つだけです。<b>Fargateでサーバー管理をなくし、Aurora Serverless v2でアイドル時のコストを抑え、マルチAZとプライベートサブネットで可用性とセキュリティを確保</b>します。複数要件の設問では、1つでも落とす選択肢を機械的に外していくのが最短です。","reasons":[{"l":"A","html":"EC2上のMySQLはパッチ適用・バックアップ・フェイルオーバーをすべて自前で運用することになり、④に反します。DB層の可用性も担保されません。"},{"l":"C","html":"単一AZ構成のため②を満たしません。同居構成は障害の影響範囲も広がります。"},{"l":"D","html":"RDSシングルAZは②を満たさず、パブリックサブネットへの配置は③に反します。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.3 AWS Fargate</a> ／ <a href=\"#database\" data-go=\"database\">第4章 4.2 Amazon Aurora</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.2 データ保護</a>"}]},{"id":"exam-set-07","file":"set-07.md","num":"問題セット07","title":"頻出①：ネットワークと名前解決","questions":[{"n":1,"topic":"SG と NACL","level":2,"body":["プライベートサブネットのEC2インスタンスから外部APIへのHTTPS通信が失敗します。セキュリティグループはアウトバウンドをすべて許可しており、ルートテーブルにはNAT Gateway宛てのデフォルトルートがあります。ネットワークACLではアウトバウンドでポート443を許可していますが、インバウンドはHTTPの80番のみ許可しています。原因として最も適切なものはどれですか。"],"options":[{"l":"A","html":"セキュリティグループのインバウンドで443番を許可していないため"},{"l":"B","html":"ネットワークACLは<b>ステートレス</b>であるため、戻りの通信（エフェメラルポート1024〜65535）をインバウンドで許可する必要がある"},{"l":"C","html":"NAT Gatewayがパブリックサブネットに配置されていないため"},{"l":"D","html":"ルートテーブルにインターネットゲートウェイ宛ての経路がないため"}],"answer":["B"],"multi":false,"req":"","key":"<b>セキュリティグループはステートフル（戻りは自動許可）／ネットワークACLはステートレス（往路と復路を別々に許可）</b>。NACLを触った直後の疎通不良は、まずエフェメラルポートの許可漏れを疑います。","reasons":[{"l":"A","html":"SGはステートフルなので、アウトバウンドで開始した通信の戻りはインバウンド許可がなくても通ります。"},{"l":"C","html":"NAT Gatewayの配置が誤っていれば通信は一切成立しません。設問はNACLの443アウトバウンドだけを許可した状態を示しており、原因の切り分けとして整合しません。"},{"l":"D","html":"プライベートサブネットのルートはNAT Gateway宛てが正しく、IGW宛てを設定するとプライベートサブネットの定義に反します。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路と認可の区別</a>"},{"n":2,"topic":"SG と NACL","level":2,"body":["特定の国から不正アクセスが集中しており、判明している数個の<b>送信元IPアドレスからのアクセスをサブネット単位で遮断</b>したいと考えています。適切な方法はどれですか。"],"options":[{"l":"A","html":"ネットワークACLのインバウンドルールで、対象IPを拒否（DENY）する"},{"l":"B","html":"セキュリティグループのインバウンドルールで、対象IPを拒否（DENY）する"},{"l":"C","html":"セキュリティグループから、対象IP以外をすべて許可するルールを作成する"},{"l":"D","html":"ルートテーブルで対象IP宛ての経路をブラックホールにする"}],"answer":["A"],"multi":false,"req":"","key":"<b>「拒否（DENY）ルールを書けるのはNACLだけ」「NACLはサブネット単位」</b>。特定IPの遮断はNACLの典型的な用途です。","reasons":[{"l":"B","html":"セキュリティグループは<b>許可ルールしか書けません</b>。拒否ルールという概念がありません。"},{"l":"C","html":"「対象IP以外をすべて許可」はSGでは事実上表現できず（許可の列挙になる）、運用も破綻します。"},{"l":"D","html":"ルートテーブルは宛先による経路制御で、送信元IPによる遮断はできません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.2 通信制御</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":3,"topic":"Route 53","level":3,"body":["同じWebアプリケーションを東京・アイルランド・オレゴンの3リージョンで運用しています。要件は「<b>利用者が最も応答の速いリージョンへ接続される</b>こと」です。適切なルーティングポリシーはどれですか。"],"options":[{"l":"A","html":"位置情報ルーティング（Geolocation）"},{"l":"B","html":"レイテンシーベースルーティング"},{"l":"C","html":"加重ルーティング"},{"l":"D","html":"複数値回答ルーティング"}],"answer":["B"],"multi":false,"req":"","key":"<b>「速い＝レイテンシーベース」「どこの国の人か＝位置情報」</b>。物理的な近さと実際の遅延は一致しないため、応答速度が要件ならレイテンシーベースです。","reasons":[{"l":"A","html":"位置情報は利用者の所在地で振り分ける方式で、<b>言語別サイトの出し分けや法規制によるアクセス制限</b>が用途です。必ずしも最速のリージョンにはなりません。"},{"l":"C","html":"加重は割合の指定で、A/Bテストや段階的な移行に使います。"},{"l":"D","html":"複数値回答は複数のIPをヘルスチェック付きで返す簡易な分散で、遅延の最小化は行いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":4,"topic":"Route 53","level":2,"body":["<code>example.com</code>（ゾーン頂点／Zone Apex）へのアクセスを、Application Load Balancerへ向ける必要があります。追加のクエリ料金は避けたいと考えています。適切な設定はどれですか。"],"options":[{"l":"A","html":"ALBのIPアドレスを調べてAレコードに静的に設定する"},{"l":"B","html":"ALBのDNS名を指すCNAMEレコードを作成する"},{"l":"C","html":"ALBを指すエイリアス（ALIAS）レコードをAレコードとして作成する"},{"l":"D","html":"<code>www.example.com</code> へのリダイレクト用にNSレコードを作成する"}],"answer":["C"],"multi":false,"req":"","key":"<b>CNAMEはゾーン頂点に設定できません</b>。AWSリソース（ALB・CloudFront・S3・API Gatewayなど）へはエイリアスレコードを使い、これは<b>クエリ料金も無料</b>です。","reasons":[{"l":"A","html":"ALBのIPアドレスは動的に変化するため、静的な設定は障害の原因になります。"},{"l":"B","html":"DNSの仕様上、ゾーン頂点にCNAMEは設定できません（サブドメインなら可）。"},{"l":"D","html":"NSレコードはゾーンの委任に使うもので、リダイレクトの手段ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":5,"topic":"VPC間接続","level":3,"body":["3つの部門VPC（A・B・C）があり、AとB、AとCの間でVPCピアリングを構成済みです。新たに<b>BとCの間でも通信</b>したいという要望が出ました。さらに今後VPCは20以上に増える見込みです。適切な対応はどれですか。"],"options":[{"l":"A","html":"各VPCにNAT Gatewayを配置し、インターネット経由で相互接続する"},{"l":"B","html":"VPC AのルートテーブルにBとCを相互に転送する経路を追加する"},{"l":"C","html":"BとCの間に新たなVPCピアリング接続を作成する"},{"l":"D","html":"AWS Transit Gatewayを導入し、各VPCをアタッチしてハブ＆スポーク構成にする"}],"answer":["D"],"multi":false,"req":"","key":"VPCピアリングは<b>推移的ルーティングができず</b>、接続数はVPC数の増加に対して急激に増えます（n×(n-1)/2）。<b>多数のVPCを相互接続するならTransit Gateway</b>が定石です。","reasons":[{"l":"A","html":"インターネット経由は遅延・コスト・セキュリティのいずれでも不利で、プライベート接続の要件を満たしません。"},{"l":"B","html":"ピアリングでは中継（推移的ルーティング）ができないため、この設定は機能しません。"},{"l":"C","html":"今回は動作しますが、20以上のVPCでは管理すべきピアリング接続が爆発的に増え、要件に耐えません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.3 VPCの外部接続</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ネットワーク</a>"},{"n":6,"topic":"ネットワーク監視","level":2,"body":["セキュリティ調査のため、特定のEC2インスタンスに出入りする通信を分析する必要があります。要件は (1) 拒否された通信も含めて<b>接続の記録</b>を残す、(2) 疑わしい通信については<b>パケットの中身</b>まで確認する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"VPCフローログで接続記録を取得し、パケットの中身はVPCトラフィックミラーリングで取得する"},{"l":"B","html":"VPCフローログのみを有効化し、ログからペイロードを抽出する"},{"l":"C","html":"CloudTrailのデータイベントで両方を記録する"},{"l":"D","html":"AWS Configで両方を記録する"}],"answer":["A"],"multi":false,"req":"","key":"<b>VPCフローログはメタデータ（送信元・宛先・ポート・許可/拒否）だけで、ペイロードは記録しません</b>。中身が必要ならトラフィックミラーリングです。","reasons":[{"l":"B","html":"フローログにはパケットの中身が含まれないため、要件(2)を満たせません。"},{"l":"C","html":"CloudTrailは<b>AWSのAPI呼び出し</b>の記録で、インスタンス間のネットワーク通信は対象外です。"},{"l":"D","html":"Configはリソースの設定状態と変更履歴を扱うサービスで、通信の記録はしません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a>"},{"n":7,"topic":"ロードバランサー","level":2,"body":["Auto Scalingグループのスケールインが発生すると、<b>処理中のリクエストが途中で切断される</b>という苦情が出ています。1リクエストの処理には最大60秒かかります。適切な対処はどれですか。"],"options":[{"l":"A","html":"Auto Scalingグループのクールダウン期間を延長する"},{"l":"B","html":"ALBのアイドルタイムアウトを60秒未満に短縮する"},{"l":"C","html":"スティッキーセッションを有効にする"},{"l":"D","html":"ターゲットグループの「登録解除の遅延（接続ドレイニング）」を、処理の最大所要時間より長く設定する"}],"answer":["D"],"multi":false,"req":"","key":"<b>登録解除の遅延（既定300秒）</b>は、ターゲットを外す際に処理中のリクエストが完了するのを待つ設定です。「スケールイン時に通信が切れる」はこの値を疑います。","reasons":[{"l":"A","html":"クールダウンは次のスケーリング動作までの待機時間で、進行中のリクエストには影響しません。"},{"l":"B","html":"アイドルタイムアウトは無通信状態の接続を切るまでの時間で、短くすると切断は増えます。"},{"l":"C","html":"スティッキーセッションは振り分け先の固定であり、終了処理中の完了待ちとは無関係です。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.5 負荷分散（ELB）</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.2 EC2 Auto Scaling</a>"},{"n":8,"topic":"エッジでの処理","level":3,"body":["CloudFrontで配信しているサイトに、次の2つの処理を追加します。それぞれに適したサービスはどれですか。","1. すべてのビューアリクエストに対し、<b>HTTPヘッダーを書き換え、URLを正規化する</b>（数万リクエスト/秒、1ミリ秒未満で完結）","2. オリジンへ転送する直前に、<b>外部の認可APIを呼び出して</b>アクセス可否を判定する"],"options":[{"l":"A","html":"1: CloudFront Functions ／ 2: Lambda@Edge"},{"l":"B","html":"1: Lambda@Edge ／ 2: CloudFront Functions"},{"l":"C","html":"1: CloudFront Functions ／ 2: CloudFront Functions"},{"l":"D","html":"1: AWS WAF ／ 2: Lambda@Edge"}],"answer":["A"],"multi":false,"req":"","key":"<b>CloudFront Functionsはビューア側のみ・JavaScript・サブミリ秒・超高頻度で安価</b>、ヘッダー操作やURL書き換えに使います。<b>Lambda@Edgeはオリジン側でも動作し、ネットワークアクセスや重い処理が可能</b>です。","reasons":[{"l":"B","html":"役割が逆です。CloudFront Functionsは外部へのネットワークアクセスができません。"},{"l":"C","html":"要件2は外部API呼び出しを含むため、CloudFront Functionsでは実現できません。"},{"l":"D","html":"WAFはリクエストの検査と遮断を行うもので、ヘッダーの書き換えやURL正規化の用途ではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.6 CloudFrontとGlobal Accelerator</a> ／ <a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a>"},{"n":9,"topic":"ハイブリッドDNS","level":3,"body":["オンプレミスのデータセンターとAWSをDirect Connectで接続しています。要件は (1) <b>オンプレミスのサーバーから、VPC内のプライベートホストゾーンの名前を解決</b>できるようにする、(2) <b>VPC内のEC2から、オンプレミスのADドメインの名前を解決</b>できるようにする、の2つです。適切な構成はどれですか。"],"options":[{"l":"A","html":"各EC2の <code>/etc/hosts</code> にオンプレミスのホスト名を記載し、オンプレ側のDNSにVPCのIPを静的登録する"},{"l":"B","html":"Route 53のパブリックホストゾーンに、両方のレコードを登録する"},{"l":"C","html":"Route 53 Resolverの<b>インバウンドエンドポイント</b>（要件1）と<b>アウトバウンドエンドポイント＋転送ルール</b>（要件2）を構成する"},{"l":"D","html":"AWS Directory Serviceの Simple AD を構築する"}],"answer":["C"],"multi":false,"req":"","key":"<b>インバウンド＝オンプレからAWSへ問い合わせる入口／アウトバウンド＝AWSからオンプレへ問い合わせる出口</b>。方向で名前が決まります。","reasons":[{"l":"A","html":"台数が増えるほど保守が破綻し、動的な変更にも追随できません。"},{"l":"B","html":"プライベートホストゾーンの名前をパブリックDNSに公開することになり、内部情報の露出という別の問題を生みます。"},{"l":"D","html":"Simple ADはディレクトリサービスであり、双方向のDNS転送を構成する仕組みではありません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.4 名前解決：Route 53 と Resolver</a>"},{"n":10,"topic":"IPv6とアウトバウンド","level":2,"body":["IPv6のみで構成したプライベートサブネットのEC2インスタンスから、<b>インターネット上のパッケージリポジトリへアウトバウンド通信のみ</b>を許可したいと考えています。インターネット側からの接続開始は拒否する必要があります。適切な構成はどれですか。"],"options":[{"l":"A","html":"NAT Gatewayを作成し、<code>::/0</code> の経路を向ける"},{"l":"B","html":"Egress-Only インターネットゲートウェイを作成し、<code>::/0</code> の経路を向ける"},{"l":"C","html":"インターネットゲートウェイを作成し、<code>::/0</code> の経路を向ける"},{"l":"D","html":"NATインスタンスを作成し、IPv6のNAT変換を有効にする"}],"answer":["B"],"multi":false,"req":"","key":"<b>IPv6にはNATの概念がありません</b>。アウトバウンド専用の出口は<b>Egress-Only インターネットゲートウェイ</b>（ステートフル）を使います。","reasons":[{"l":"A","html":"NAT GatewayはIPv4専用です（IPv6のトラフィックは扱いません）。"},{"l":"C","html":"IGWを向けると双方向に到達可能となり、インターネット側からの接続開始を拒否する要件に反します。"},{"l":"D","html":"IPv6でのNAT変換という仕組み自体がなく、NATインスタンスの運用負荷も要件に合いません。"}],"refs":"<a href=\"#network\" data-go=\"network\">第3章 3.1 VPCの基礎</a>"}]},{"id":"exam-set-08","file":"set-08.md","num":"問題セット08","title":"頻出②：ストレージの選択とデータ移行","questions":[{"n":1,"topic":"共有ストレージの選択","level":2,"body":["Linux上で動くコンテンツ管理システムを、複数のEC2インスタンスへスケールアウトします。各インスタンスは<b>同じディレクトリを同時に読み書き</b>する必要があり、容量は使用量に応じて自動的に増減してほしいと考えています。適切なストレージはどれですか。"],"options":[{"l":"A","html":"Amazon S3をファイルシステムとしてマウントする"},{"l":"B","html":"Amazon EBS（gp3）を各インスタンスにアタッチする"},{"l":"C","html":"Amazon EBS Multi-Attach（io2）"},{"l":"D","html":"Amazon EFS"}],"answer":["D"],"multi":false,"req":"","key":"<b>「複数のインスタンスから同時にマウント」「Linux／NFS」「容量の自動拡張」＝EFS</b>。マルチAZに分散配置されるため可用性も高まります。","reasons":[{"l":"A","html":"S3はオブジェクトストレージで、POSIXのファイルロックや部分更新を前提とするCMSの用途には向きません。"},{"l":"B","html":"EBSは単一インスタンスにアタッチするブロックストレージで、別々のボリュームになるため内容を共有できません。"},{"l":"C","html":"Multi-Attachは<b>io1/io2かつ同一AZ限定</b>で、さらにクラスタ対応ファイルシステムの導入が前提です。一般的なファイル共有には適しません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.3 Amazon EFS</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ストレージ</a>"},{"n":2,"topic":"共有ストレージの選択","level":2,"body":["社内の<b>Windowsファイルサーバー</b>をAWSへ移行します。要件は (1) SMBプロトコルで既存のクライアントからそのまま接続できる、(2) <b>Active Directoryのユーザー権限（NTFS ACL）をそのまま使う</b>、(3) サーバーの運用をやめたい、の3つです。適切なサービスはどれですか。"],"options":[{"l":"A","html":"Amazon FSx for Lustre"},{"l":"B","html":"Amazon EFS"},{"l":"C","html":"Amazon FSx for Windows File Server"},{"l":"D","html":"EC2にWindows Serverを構築してファイルサーバーにする"}],"answer":["C"],"multi":false,"req":"","key":"<b>Windows・SMB・Active Directory統合・NTFS ACL</b>というキーワードが揃えばFSx for Windows File Serverです。","reasons":[{"l":"A","html":"FSx for LustreはHPC・機械学習向けの高スループット並列ファイルシステムで、用途が異なります。"},{"l":"B","html":"EFSはLinux向けのNFSで、SMBやNTFS ACLには対応しません。"},{"l":"D","html":"OSのパッチ適用やバックアップなど運用が残り、要件(3)に反します。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.4 Amazon FSx</a> ／ <a href=\"#cmp\" data-go=\"cmp\">付録A ストレージ</a>"},{"n":3,"topic":"ハイブリッドストレージ","level":3,"body":["オンプレミスのバックアップソフトウェアが、物理テープライブラリへバックアップを書き出しています。テープ装置を廃止したいものの、<b>バックアップソフトウェアは変更したくありません</b>。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS DataSync"},{"l":"B","html":"AWS Storage Gateway の S3 File Gateway"},{"l":"C","html":"AWS Storage Gateway の Tape Gateway（仮想テープライブラリ）"},{"l":"D","html":"AWS Backup"}],"answer":["C"],"multi":false,"req":"","key":"<b>「既存のバックアップソフトのテープ装置をそのまま置き換える」＝Tape Gateway（VTL）</b>。バックアップソフトからは従来のテープ装置に見え、実体はS3／Glacierに保管されます。","reasons":[{"l":"A","html":"DataSyncはファイルの転送サービスで、テープ装置としては振る舞いません。"},{"l":"B","html":"File GatewayはNFS/SMBのファイル共有として見せる方式で、テープインターフェースは提供しません。"},{"l":"D","html":"AWS BackupはAWSリソースのバックアップを一元管理するサービスで、オンプレのバックアップソフトのテープ出力先にはなりません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":4,"topic":"移行方式の選択","level":3,"body":["オンプレミスのNASに蓄積された<b>300 TB</b>のデータをS3へ移行します。拠点のインターネット回線は実効 <b>100 Mbps</b> で、業務時間帯は帯域を空けられません。移行はできるだけ短期間で完了させたい考えです。適切な方法はどれですか。"],"options":[{"l":"A","html":"S3 Transfer Acceleration を有効化してアップロードする"},{"l":"B","html":"AWS DataSync でインターネット経由の転送をスケジュール実行する"},{"l":"C","html":"AWS Transfer Family のSFTPエンドポイントへアップロードする"},{"l":"D","html":"AWS Snowball Edge を利用して物理デバイスで移送する"}],"answer":["D"],"multi":false,"req":"","key":"<b>回線容量と転送量の比</b>で判断します。100 Mbps で 300 TB は、理論値でも <b>270日以上</b>（300 TB ÷ 100 Mbps ≒ 6,600時間超）かかります。<b>回線が細い／データが大きい／期限がある</b>ならSnow Familyの物理移送です。","reasons":[{"l":"A","html":"Transfer Accelerationは遠距離のレイテンシを改善する機能で、帯域そのものを増やすわけではありません。"},{"l":"B","html":"DataSyncは転送を効率化しますが、<b>物理的な回線容量の上限は超えられません</b>。"},{"l":"C","html":"Transfer Familyは既存のSFTP運用を維持するためのサービスで、大容量の一括移行手段ではありません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.15 その他の移行サービス</a> ／ <a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a>"},{"n":5,"topic":"移行方式の選択","level":2,"body":["オンプレミスのNFSサーバーにある <b>2 TB</b> のファイルを、毎晩Amazon EFSへ同期します。差分のみを効率よく転送し、転送後にデータの整合性も検証したいと考えています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS DataSync"},{"l":"B","html":"AWS Storage Gateway の S3 File Gateway"},{"l":"C","html":"rsync を cron で実行するスクリプトをEC2上に構築する"},{"l":"D","html":"AWS Snowcone"}],"answer":["A"],"multi":false,"req":"","key":"<b>「オンプレ↔AWSの定期的なファイル同期」「増分転送」「整合性チェック」＝DataSync</b>。NFS/SMB/HDFSからS3・EFS・FSxへ転送できます。","reasons":[{"l":"B","html":"Storage Gatewayは<b>オンプレから使い続ける</b>ためのハイブリッド運用の仕組みで、同期ジョブの管理は行いません。"},{"l":"C","html":"自前実装は保守・監視・再試行・整合性検証をすべて自分で担うことになります。"},{"l":"D","html":"Snowconeは物理デバイスによる少量データの移送用で、毎晩の同期には使えません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.13 AWS DataSync</a> ／ <a href=\"#storage\" data-go=\"storage\">第2章 2.6 AWS Storage Gateway</a>"},{"n":6,"topic":"データベース移行","level":3,"body":["オンプレミスのOracleデータベース（4 TB）をAmazon Aurora PostgreSQLへ移行します。要件は (1) <b>停止時間を数分以内</b>に抑える、(2) スキーマとストアドプロシージャを変換する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"AWS DMSのフルロードのみを実行し、完了後にアプリケーションを切り替える"},{"l":"B","html":"AWS SCT（Schema Conversion Tool）でスキーマを変換し、AWS DMSの継続的レプリケーション（CDC）で差分同期してから切り替える"},{"l":"C","html":"Oracleのデータポンプでエクスポートし、S3経由でインポートする"},{"l":"D","html":"AWS DataSyncでデータファイルを転送する"}],"answer":["B"],"multi":false,"req":"","key":"<b>異種DB移行＝SCT（スキーマ変換）＋DMS（データ移行）</b>、<b>停止時間の最小化＝CDCによる継続的レプリケーション</b>。この組み合わせが定番です。","reasons":[{"l":"A","html":"フルロードのみでは、ロード中の更新が反映されず、停止時間もデータ量に比例して長くなります。"},{"l":"C","html":"データポンプは同種DB間の手段で、PostgreSQLへの異種移行ではスキーマ変換の問題が残り、停止時間も長くなります。"},{"l":"D","html":"DataSyncはファイル転送サービスで、稼働中のDBの論理的な移行には使えません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.12 AWS Database Migration Service</a>"},{"n":7,"topic":"外部連携","level":2,"body":["取引先30社が、毎日<b>SFTPクライアント</b>でファイルを送信してきます。現在はEC2上にSFTPサーバーを構築して運用していますが、パッチ適用と可用性の確保が負担です。取引先の接続方法は変更できません。適切な移行先はどれですか。"],"options":[{"l":"A","html":"AWS Transfer Family のSFTPエンドポイントを作成し、保存先をS3にする"},{"l":"B","html":"S3の事前署名URLを毎日発行して取引先へ配布する"},{"l":"C","html":"AWS DataSyncのエージェントを取引先に導入してもらう"},{"l":"D","html":"Amazon AppFlowで取引先のシステムと連携する"}],"answer":["A"],"multi":false,"req":"","key":"<b>「取引先の既存SFTPクライアントを変えられない」「サーバー運用をやめたい」＝Transfer Family</b>。認証はIAM・Active Directory・カスタムIDプロバイダーと連携でき、保存先はS3またはEFSです。","reasons":[{"l":"B","html":"接続方法の変更を取引先に強いることになり、前提に反します。"},{"l":"C","html":"取引先側にエージェント導入を求めるのは現実的でなく、DataSyncの用途とも異なります。"},{"l":"D","html":"AppFlowはSaaS（SalesforceやZendeskなど）との連携用で、SFTPの受け口にはなりません。"}],"refs":"<a href=\"#others\" data-go=\"others\">第10章 10.14 AWS Transfer Family</a>"},{"n":8,"topic":"S3のデータ保護","level":3,"body":["コンプライアンス要件により、S3バケットのオブジェクトを<b>別リージョンへ複製</b>することになりました。設定後に確認すると、<b>既存のオブジェクトが複製されていません</b>。原因と対処として正しいものはどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"レプリケーションは設定後に作成・更新されたオブジェクトが対象のため、既存分はS3バッチレプリケーションで複製する"},{"l":"B","html":"既存オブジェクトを複製するには、バケットのリージョンを変更する必要がある"},{"l":"C","html":"レプリケーション先のストレージクラスをGlacierにすれば既存オブジェクトも複製される"},{"l":"D","html":"レプリケーションはライフサイクルポリシーで設定するため、移行日数を0日にすれば既存分も対象になる"},{"l":"E","html":"レプリケーションにはソースと宛先の両方のバケットで<b>バージョニングの有効化</b>が必要である"}],"answer":["A","E"],"multi":true,"req":"","key":"レプリケーションの前提は<b>バージョニング</b>、対象は<b>設定後の変更分</b>。既存オブジェクトは<b>バッチレプリケーション</b>で別途複製します。","reasons":[{"l":"B","html":"バケットのリージョンは作成後に変更できません。"},{"l":"C","html":"宛先のストレージクラスは複製対象の範囲とは無関係です。"},{"l":"D","html":"レプリケーションとライフサイクルは別の機能で、ライフサイクルで複製を起こすことはできません。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.5 高可用性と耐障害性</a>"},{"n":9,"topic":"EC2のストレージ","level":2,"body":["動画のトランスコード処理を行うEC2インスタンスで、<b>処理中の一時ファイル</b>を最速のディスクに置きたいと考えています。一時ファイルは処理が終われば不要で、インスタンスの停止・終了時に失われても構いません。適切なストレージはどれですか。"],"options":[{"l":"A","html":"EBS gp3"},{"l":"B","html":"インスタンスストア（NVMe SSD）"},{"l":"C","html":"EBS st1"},{"l":"D","html":"Amazon EFS"}],"answer":["B"],"multi":false,"req":"","key":"<b>インスタンスストアは物理サーバー直結で最速</b>。<b>停止・終了でデータが消える</b>（再起動では消えない）という性質が、一時ファイルの用途と一致します。","reasons":[{"l":"A","html":"gp3は永続ストレージで十分高速ですが、ネットワーク越しのためインスタンスストアのレイテンシには及びません。"},{"l":"C","html":"st1はHDDでシーケンシャルなスループット向け、ランダムI/Oの多い一時領域には不適です。"},{"l":"D","html":"EFSはネットワーク共有ファイルシステムで、一時ファイル用途では遅く、コストも無駄になります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.2 Amazon EBS</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"},{"n":10,"topic":"大容量アップロード","level":2,"body":["海外の拠点から、<b>1ファイルあたり20 GB</b>の測定データをS3（東京リージョン）へ毎日アップロードしています。アップロードの失敗が多く、完了までの時間も長いという問題があります。適切な対処はどれですか。<b>2つ選択してください。</b>"],"options":[{"l":"A","html":"ストレージクラスをS3 Standard-IAに変更する"},{"l":"B","html":"アップロード先のバケットでバージョニングを有効化する"},{"l":"C","html":"マルチパートアップロードを使い、分割して並列にアップロードする"},{"l":"D","html":"S3 Transfer Accelerationを有効化し、最寄りのエッジロケーション経由で転送する"},{"l":"E","html":"ファイルをGlacier Deep Archiveへ直接アップロードする"}],"answer":["C","D"],"multi":true,"req":"","key":"<b>単一PUTの上限は5 GB</b>であり、20 GBのファイルは<b>マルチパートアップロードが必須</b>です（分割・並列・再試行が可能になり、失敗にも強くなります）。加えて<b>遠距離からの転送はTransfer Acceleration</b>で改善します。","reasons":[{"l":"A","html":"ストレージクラスは保管コストの話で、アップロードの速度や成功率には影響しません。"},{"l":"B","html":"バージョニングは誤削除・上書き対策で、転送の問題には関係しません。"},{"l":"E","html":"アーカイブクラスへ直接置いても転送は速くならず、取り出しにも時間がかかるようになります。"}],"refs":"<a href=\"#storage\" data-go=\"storage\">第2章 2.1 Amazon S3</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.1 ストレージとパフォーマンス</a>"}]},{"id":"exam-set-09","file":"set-09.md","num":"問題セット09","title":"頻出③：ID・運用・サーバーレス連携","questions":[{"n":1,"topic":"認証の主体","level":3,"body":["3つのID管理の要件があります。それぞれに最も適したサービスの組み合わせはどれですか。","1. モバイルアプリの<b>エンドユーザー数百万人</b>のサインアップ・サインインを実装したい","2. 社員が<b>50個のAWSアカウント</b>へ、既存のIdP（Okta）のIDでログインできるようにしたい","3. AWS上のWindows Serverを、<b>オンプレミスのActive Directory</b>のユーザーで認証させたい（AWS側にディレクトリを置かない）"],"options":[{"l":"A","html":"1: IAM Identity Center ／ 2: Amazon Cognito ／ 3: AWS Managed Microsoft AD"},{"l":"B","html":"1: Amazon Cognito ／ 2: IAM Identity Center ／ 3: AD Connector"},{"l":"C","html":"1: Amazon Cognito ／ 2: IAMユーザーとグループ ／ 3: Simple AD"},{"l":"D","html":"1: AWS Directory Service ／ 2: IAM Identity Center ／ 3: Amazon Cognito"}],"answer":["B"],"multi":false,"req":"","key":"<b>アプリの利用者＝Cognito／AWSを操作する社員＝IAM Identity Center／Windowsのドメイン認証＝Directory Service</b>。さらにDirectory Serviceの中では「<b>AWS側にディレクトリを置かず、オンプレADへ転送する＝AD Connector</b>」です。","reasons":[{"l":"A","html":"1と2が逆です。Identity Centerは社内の管理者・開発者向けで、一般消費者のサインアップには使いません。"},{"l":"C","html":"50アカウントに個別のIAMユーザーを作る運用は破綻します。Simple ADはオンプレADとの信頼関係を張れず、要件3を満たしません。"},{"l":"D","html":"Directory Serviceは消費者向けのサインアップ基盤ではなく、Cognitoはドメイン参加の認証を提供しません。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.2 IAM Identity Center</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.3 AWS Directory Service</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.4 Amazon Cognito</a>"},{"n":2,"topic":"ポリシー評価","level":3,"body":["あるIAMロールには<code>AmazonS3FullAccess</code>が付与されています。しかし、そのアカウントが所属するOUに適用されたSCPで、<code>s3:DeleteObject</code>が明示的に拒否されています。さらに対象バケットのバケットポリシーでは、当該ロールに対して<code>s3:*</code>が明示的に許可されています。このロールは対象バケットのオブジェクトを削除できますか。"],"options":[{"l":"A","html":"できる。SCPはルートユーザーにのみ適用されるため"},{"l":"B","html":"できる。バケットポリシーでの明示的な許可が、SCPの拒否を上書きするため"},{"l":"C","html":"できる。IAMポリシーとバケットポリシーの両方で許可されているため"},{"l":"D","html":"できない。SCPによる明示的な拒否は、他のどの許可よりも優先されるため"}],"answer":["D"],"multi":false,"req":"","key":"<b>明示的な拒否（Deny）はすべての許可に優先</b>します。SCP・IAMポリシー・リソースポリシーのどこか1つでも拒否があれば、その操作は実行できません。","reasons":[{"l":"A","html":"SCPはメンバーアカウント内のすべてのプリンシパル（ルートユーザーを含む）に適用されます。管理アカウントには効かない、という点との混同に注意します。"},{"l":"B","html":"リソースポリシーの許可がSCPの拒否を上書きすることはありません。評価順の理解を問う典型的な誤答です。"},{"l":"C","html":"「複数箇所で許可されている＝実行できる」ではありません。拒否の有無が先に効きます。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.1 AWS IAM</a> ／ <a href=\"#d1\" data-go=\"d1\">第11章 11.1 アクセス管理</a>"},{"n":3,"topic":"資格情報の管理","level":2,"body":["アプリケーションの設定値と資格情報をAWSで管理します。要件は (1) RDSのマスターパスワードを<b>30日ごとに自動でローテーション</b>する、(2) アプリの機能フラグなど<b>数百件の設定値を無料で</b>保管する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"1: AWS KMS ／ 2: Amazon S3"},{"l":"B","html":"1: AWS Systems Manager Parameter Store ／ 2: AWS Secrets Manager"},{"l":"C","html":"1: AWS Secrets Manager ／ 2: AWS Systems Manager Parameter Store"},{"l":"D","html":"1: AWS Secrets Manager ／ 2: AWS Secrets Manager"}],"answer":["C"],"multi":false,"req":"","key":"<b>自動ローテーションが要件にあるか</b>で決まります。あればSecrets Manager（RDS等と統合済み・有料）、なければParameter Store（標準パラメータは無料、SecureStringでKMS暗号化）。","reasons":[{"l":"A","html":"KMSは鍵の管理サービスで、資格情報そのものの保管・ローテーションは行いません。S3に平文で置くのは論外です。"},{"l":"B","html":"Parameter Storeの標準機能には、RDSと統合した自動ローテーションはありません。"},{"l":"D","html":"Secrets Managerはシークレット1件あたりの月額課金があるため、数百件の一般的な設定値には割高です。"}],"refs":"<a href=\"#security\" data-go=\"security\">第5章 5.10 Secrets Manager vs Parameter Store</a>"},{"n":4,"topic":"監視","level":2,"body":["EC2インスタンスの<b>メモリ使用率</b>と<b>ディスクの空き容量</b>が、CloudWatchのメトリクス一覧に表示されず、しきい値アラームを設定できません。適切な対処はどれですか。"],"options":[{"l":"A","html":"CloudWatchエージェントをインスタンスに導入し、カスタムメトリクスとして送信する"},{"l":"B","html":"詳細モニタリングを有効化し、取得間隔を1分にする"},{"l":"C","html":"インスタンスにIAMロールを付与すれば、標準メトリクスとして自動的に収集される"},{"l":"D","html":"VPCフローログを有効化する"}],"answer":["A"],"multi":false,"req":"","key":"CloudWatchの標準メトリクスは<b>ハイパーバイザー視点</b>で取得されるため、<b>OSの内部情報であるメモリ使用率やディスク空き容量は含まれません</b>。エージェントの導入が必要です（試験の頻出ポイント）。","reasons":[{"l":"B","html":"詳細モニタリングは取得<b>間隔</b>を5分から1分にするもので、取得できる<b>種類</b>は増えません。"},{"l":"C","html":"IAMロールはエージェントがメトリクスを送信するために必要ですが、ロールだけでは収集されません。"},{"l":"D","html":"フローログはネットワーク通信の記録で、OSのリソース使用率とは無関係です。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.1 Amazon CloudWatch</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":5,"topic":"監視と統制","level":3,"body":["セキュリティ監査の指摘に対応します。要件は (1) <b>ルートユーザーによるログインが発生したら即座に通知</b>する、(2) <b>S3バケットが公開設定になっていないかを継続的に評価し、違反を自動修復</b>する、の2つです。適切な組み合わせはどれですか。"],"options":[{"l":"A","html":"1: AWS Config ルール ／ 2: CloudTrail のデータイベント"},{"l":"B","html":"1: CloudTrail → CloudWatch Logs のメトリクスフィルタ＋アラーム → SNS ／ 2: AWS Config ルール＋修復アクション"},{"l":"C","html":"1: Amazon GuardDuty ／ 2: Amazon Macie"},{"l":"D","html":"1: AWS Trusted Advisor ／ 2: Amazon Inspector"}],"answer":["B"],"multi":false,"req":"","key":"<b>「特定のAPI操作をリアルタイムに検知」＝CloudTrail＋メトリクスフィルタ＋アラーム</b>、<b>「設定が基準に沿っているかを継続評価し直す」＝Config ルール＋修復アクション（SSM Automation）</b>。","reasons":[{"l":"A","html":"Configは設定状態の評価であり、ログイン操作そのものの通知には向きません。データイベントはS3オブジェクト操作等の記録で、公開設定の評価はしません。"},{"l":"C","html":"GuardDutyは脅威検知、Macieは機密データの発見で、いずれも設定の準拠評価や自動修復の仕組みではありません。"},{"l":"D","html":"Trusted Advisorは定期的な点検、Inspectorは脆弱性診断で、要件の即時通知・自動修復には対応しません。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.2 AWS CloudTrail</a> ／ <a href=\"#management\" data-go=\"management\">第8章 8.7 AWS Config</a>"},{"n":6,"topic":"イベント駆動","level":2,"body":["次の2つの自動化を実装します。それぞれに適したサービスはどれですか。","1. <b>毎日深夜2時</b>に、未使用リソースを棚卸しするLambda関数を実行する","2. <b>RDSインスタンスの障害イベントが発生したら</b>、運用チームのSlackへ通知する"],"options":[{"l":"A","html":"1: Amazon EventBridge（スケジュール式） ／ 2: Amazon EventBridge（イベントパターン）"},{"l":"B","html":"1: Amazon SQSの遅延キュー ／ 2: Amazon SNS"},{"l":"C","html":"1: AWS Lambdaのタイマー機能 ／ 2: AWS CloudTrail"},{"l":"D","html":"1: Amazon EventBridge（スケジュール式） ／ 2: Amazon SQS"}],"answer":["A"],"multi":false,"req":"","key":"<b>EventBridgeは「cron/rate式による定期実行」と「AWSサービスの状態変化をルールで振り分ける」の両方を担います</b>。どちらも試験の定番パターンです。","reasons":[{"l":"B","html":"SQSの遅延キューは配信を最大15分遅らせる機能で、毎日のスケジュール実行はできません。"},{"l":"C","html":"Lambda自体にスケジュール実行の機能はなく（EventBridgeが起動します）、CloudTrailは記録であって通知の振り分けは行いません。"},{"l":"D","html":"SQSはキューであり、イベントの内容に応じた振り分けや通知の役割は担いません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.3 Amazon EventBridge</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.4 イベント駆動型アーキテクチャ</a>"},{"n":7,"topic":"ワークフロー","level":3,"body":["保険金請求の処理を自動化します。処理は「書類のOCR → 内容の検証 → <b>金額が100万円を超える場合は管理者の承認を待つ</b> → 支払い」という流れで、各ステップの失敗時には再試行と補償処理が必要です。承認待ちは数日に及ぶことがあります。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Step Functions（標準ワークフロー、コールバックパターンで承認を待つ）"},{"l":"B","html":"単一のAWS Lambda関数にすべての処理を実装する"},{"l":"C","html":"Amazon SQS FIFOキューで各ステップをつなぐ"},{"l":"D","html":"Amazon EventBridgeのイベントバスで各Lambdaを連鎖させる"}],"answer":["A"],"multi":false,"req":"","key":"<b>分岐・再試行・補償処理・長時間の待機</b>を宣言的に管理できるのがStep Functionsです。標準ワークフローは<b>最大1年</b>実行でき、タスクトークンによるコールバックで人の承認を待てます。","reasons":[{"l":"B","html":"Lambdaの実行時間は<b>最大15分</b>で、数日の承認待ちは不可能です。エラー処理も自前実装になります。"},{"l":"C","html":"キューは処理の受け渡しはできますが、条件分岐・状態管理・補償処理の枠組みは提供しません。"},{"l":"D","html":"EventBridgeでの連鎖は、全体の状態把握と再試行・巻き戻しが困難で、長時間の待機状態を管理できません。"}],"refs":"<a href=\"#integration\" data-go=\"integration\">第6章 6.4 AWS Step Functions</a> ／ <a href=\"#d2\" data-go=\"d2\">第12章 12.2 疎結合アーキテクチャ</a>"},{"n":8,"topic":"コンテナの権限","level":3,"body":["Amazon ECS on Fargateで動くアプリケーションが、S3バケットへのアクセスで<code>AccessDenied</code>になります。一方、<b>ECRからのイメージ取得とCloudWatch Logsへのログ出力は正常</b>に動作しています。修正すべき対象はどれですか。"],"options":[{"l":"A","html":"サービスにアタッチされたセキュリティグループでHTTPSのアウトバウンドを許可する"},{"l":"B","html":"タスク実行ロール（task execution role）にS3へのアクセス許可を追加する"},{"l":"C","html":"EC2インスタンスプロファイルにS3へのアクセス許可を追加する"},{"l":"D","html":"タスクロール（task role）にS3へのアクセス許可を追加する"}],"answer":["D"],"multi":false,"req":"","key":"<b>タスクロール＝コンテナ内のアプリが他のAWSサービスを呼ぶための権限</b>、<b>タスク実行ロール＝ECSエージェントがイメージ取得とログ出力を行うための権限</b>。イメージ取得とログが正常なので、実行ロールは正しく機能しています。","reasons":[{"l":"A","html":"通信が遮断されていればタイムアウトになります。<code>AccessDenied</code>は<b>到達したうえで認可が拒否された</b>ことを示します。"},{"l":"B","html":"実行ロールはアプリケーションのAPI呼び出しには使われません（症状からも正常に機能していると分かります）。"},{"l":"C","html":"Fargateではインスタンスプロファイルは存在しません（EC2起動タイプの概念です）。"}],"refs":"<a href=\"#container\" data-go=\"container\">第9章 9.1 Amazon ECS</a> ／ <a href=\"#foundations\" data-go=\"foundations\">第0章 0.4 通信経路と認可の区別</a>"},{"n":9,"topic":"Lambdaの同時実行","level":3,"body":["同一アカウント内に複数のLambda関数があります。次の2つの問題が発生しました。<b>それぞれに対する適切な対処を2つ選択してください。</b>","1. 大量に起動されるバッチ用の関数が同時実行数を占有し、<b>決済APIの関数がスロットリング</b>された","2. 決済APIの関数で、<b>コールドスタートによる初回応答の遅延</b>が問題になっている"],"options":[{"l":"A","html":"決済APIの関数のタイムアウト値を15分に延長する"},{"l":"B","html":"バッチ用の関数に<b>予約済み同時実行数</b>を設定し、使用できる上限を制限する"},{"l":"C","html":"決済APIの関数に<b>プロビジョニング済み同時実行数</b>を設定する"},{"l":"D","html":"バッチ用の関数のメモリ割り当てを減らす"},{"l":"E","html":"決済APIの関数をVPC内に配置する"}],"answer":["B","C"],"multi":true,"req":"","key":"<b>予約済み同時実行＝その関数の上限を固定し、他の関数への影響を隔離する</b>（スロットリング対策）。<b>プロビジョニング済み同時実行＝あらかじめ実行環境を温めておく</b>（コールドスタート対策）。名前が似ているため役割の取り違えが頻出します。","reasons":[{"l":"A","html":"タイムアウトは1回の実行時間の上限で、同時実行数の枯渇にも初回遅延にも効きません。"},{"l":"D","html":"メモリを減らすとCPUも比例して下がり処理が遅くなるため、占有時間はむしろ延びます。"},{"l":"E","html":"VPC配置はネットワーク到達性のための設定で、コールドスタートはむしろ不利になる場合があります。"}],"refs":"<a href=\"#compute\" data-go=\"compute\">第1章 1.6 AWS Lambda</a> ／ <a href=\"#d3\" data-go=\"d3\">第13章 13.2 コンピューティングとパフォーマンス</a>"},{"n":10,"topic":"運用の自動化","level":2,"body":["数百台のEC2インスタンスに対し、OSのセキュリティパッチを<b>定期的に適用し、適用状況をレポート</b>したいと考えています。インスタンスへのSSH接続は禁止されています。適切なサービスはどれですか。"],"options":[{"l":"A","html":"AWS Config"},{"l":"B","html":"Amazon Inspector"},{"l":"C","html":"AWS Systems Manager Patch Manager（メンテナンスウィンドウで実行）"},{"l":"D","html":"Amazon EventBridge＋Lambdaで各インスタンスへSSH接続してパッチを適用する"}],"answer":["C"],"multi":false,"req":"","key":"<b>パッチ適用の自動化と準拠レポート＝Patch Manager</b>。SSMエージェント経由で動作するためSSHは不要で、メンテナンスウィンドウで実行時間帯も制御できます。","reasons":[{"l":"A","html":"Configは設定の記録と準拠評価で、OSのパッチ適用の実行者ではありません。"},{"l":"B","html":"Inspectorは脆弱性を<b>検出</b>するサービスで、パッチの適用は行いません（検出→Patch Managerで適用、という組み合わせになります）。"},{"l":"D","html":"SSH接続が禁止されている前提に反し、自前実装の保守負担も大きくなります。"}],"refs":"<a href=\"#management\" data-go=\"management\">第8章 8.4 AWS Systems Manager</a> ／ <a href=\"#security\" data-go=\"security\">第5章 5.12 Amazon Inspector</a>"}]}];
